/* Question bank: Accounting Foundations (basics) + Income Statement (is) */
FSQ.addQuestions([
  // ===================== BASICS =====================
  { id: "ba-001", topic: "basics", sub: "Accrual vs cash", difficulty: 1, type: "mc",
    prompt: "Under <b>accrual</b> accounting, when is revenue recorded?",
    choices: ["When the customer pays cash","When the goods or services are delivered (earned)","When the invoice is mailed","When the sales contract is signed"],
    answer: 1,
    explain: "Accrual accounting records revenue when it is <b>earned</b>, meaning the company has delivered what it promised, no matter when the cash shows up. Payment timing only affects the cash and A/R accounts." },
  { id: "ba-002", topic: "basics", sub: "Accrual vs cash", difficulty: 1, type: "mc",
    prompt: "Under <b>cash-basis</b> accounting, when is an expense recorded?",
    choices: ["When the cash is actually paid","When the cost is incurred","When the related revenue is earned","At the end of the fiscal year"],
    answer: 0,
    explain: "Cash-basis accounting is simple: record revenue when cash comes in and expenses when cash goes out. It ignores the matching principle, which is why public companies can't use it." },
  { id: "ba-003", topic: "basics", sub: "Accrual vs cash", difficulty: 2, type: "mc",
    prompt: "A landscaper mows a client's lawns all December and bills $800. The client pays on January 10. Under <b>accrual</b> accounting, when is the $800 of revenue recorded?",
    choices: ["$800 in January","$400 in December and $400 in January","Never, because cash came in after year-end","$800 in December"],
    answer: 3,
    explain: "The work was done in December, so the revenue is earned in December. At Dec 31 the landscaper shows an $800 account receivable, and the January payment just turns that receivable into cash. No new revenue is recorded then." },
  { id: "ba-004", topic: "basics", sub: "Accrual vs cash", difficulty: 1, type: "mc",
    prompt: "Same landscaper: lawns mowed in December, $800 paid on January 10. Under <b>cash-basis</b> accounting, when is the revenue recorded?",
    choices: ["$800 in December","$400 in each month","$800 in January","Only once the client signs a receipt"],
    answer: 2,
    explain: "Cash basis records revenue when the money arrives, which here is January. So the two methods put the same $800 in different periods." },
  { id: "ba-005", topic: "basics", sub: "Accrual vs cash", difficulty: 1, type: "tf",
    prompt: "U.S. public companies must prepare their financial statements on the accrual basis under GAAP.",
    answer: true,
    explain: "GAAP requires accrual accounting, because it matches revenue and expenses to the period they relate to. Cash-basis books are mostly used by very small businesses and for some tax purposes." },
  { id: "ba-006", topic: "basics", sub: "Accrual vs cash", difficulty: 2, type: "mc",
    prompt: "Why do investors generally prefer accrual accounting to cash accounting for judging performance?",
    choices: ["It always shows higher profits","It puts revenue and the expenses that produced it in the same period, so profit reflects what really happened that period","It eliminates the need for a cash flow statement","It is easier for small businesses to maintain"],
    answer: 1,
    explain: "Accrual accounting matches revenue with the expenses that produced it, so a lumpy payment schedule doesn't distort profit. It doesn't always show higher profit, and you still need a cash flow statement because net income and cash differ." },
  { id: "ba-007", topic: "basics", sub: "Revenue recognition", difficulty: 1, type: "mc",
    prompt: "Under ASC 606 (the U.S. revenue standard), revenue is recognized when…",
    choices: ["control of the promised good or service transfers to the customer","cash is collected from the customer","the company's board approves the sale","the product is manufactured"],
    answer: 0,
    explain: "ASC 606 centers on <b>control transfer</b>: once the customer can direct and benefit from the good or service, the company has satisfied its performance obligation and can recognize revenue." },
  { id: "ba-008", topic: "basics", sub: "Revenue recognition", difficulty: 2, type: "order",
    prompt: "Put the five steps of ASC 606 revenue recognition in order.",
    items: ["Identify the contract with the customer","Identify the performance obligations (the distinct promises)","Determine the transaction price","Allocate the price to each performance obligation","Recognize revenue when (or as) each obligation is satisfied"],
    explain: "Contract → promises → price → split the price across the promises → recognize revenue as each promise is fulfilled. One way to remember it: you can't allocate a price until you know both the price and the promises." },
  { id: "ba-009", topic: "basics", sub: "Revenue recognition", difficulty: 2, type: "mc",
    prompt: "A gym sells a 12-month membership on January 1 for $600, paid upfront. How much revenue does the gym recognize in <b>January</b>?",
    choices: ["$600","$0","$300","$50"],
    answer: 3,
    explain: "The gym earns the membership evenly over 12 months: $600 ÷ 12 = $50 per month. The other $550 sits on the balance sheet as deferred (unearned) revenue, a liability, until it's earned." },
  { id: "ba-010", topic: "basics", sub: "Revenue recognition", difficulty: 3, type: "mc",
    prompt: "The same gym sold a $600, 12-month membership on January 1 (paid upfront). How much <b>deferred revenue</b> remains on its balance sheet on March 31?",
    choices: ["$150","$600","$450","$0"],
    answer: 2,
    explain: "By March 31, three months have been earned: 3 × $50 = $150 of revenue. The rest, $600 − $150 = $450, is still owed to the member as future service, so it stays a liability." },
  { id: "ba-011", topic: "basics", sub: "Revenue recognition", difficulty: 2, type: "sort",
    prompt: "Under accrual accounting, sort each event: is it revenue earned <b>this period</b>?",
    buckets: ["Revenue earned this period","Not revenue this period"],
    items: [
      ["A bakery hands a customer a cake and is paid in cash","Revenue earned this period"],
      ["A plumber finishes a repair; the customer will pay in 30 days","Revenue earned this period"],
      ["A customer prepays for a wedding cake to be delivered next month","Not revenue this period"],
      ["A client signs a contract, but no work has started","Not revenue this period"],
      ["A software firm delivers this month's share of an annual subscription","Revenue earned this period"],
      ["The company receives a $10,000 bank loan","Not revenue this period"],
      ["A customer pays off last month's invoice","Not revenue this period"]
    ],
    explain: "Revenue is earned when you deliver. Finished work counts even if it's unpaid. Prepayments and signed-but-unstarted contracts aren't earned yet. Loans are financing, and collecting an old invoice just converts A/R into cash, so neither one is revenue." },
  { id: "ba-012", topic: "basics", sub: "Revenue recognition", difficulty: 2, type: "tf",
    prompt: "Once a customer signs a contract, the company can recognize the full contract value as revenue, even if nothing has been delivered yet.",
    answer: false,
    explain: "A signed contract is only step 1 of ASC 606. Revenue waits until the company satisfies its performance obligations by actually delivering the goods or services." },
  { id: "ba-013", topic: "basics", sub: "Revenue recognition", difficulty: 2, type: "mc",
    prompt: "A phone store sells a phone bundled with 2 years of tech support for one price. How does ASC 606 treat this?",
    choices: ["All revenue is recognized on the day the phone is handed over","The phone and the support are separate performance obligations: phone revenue at handover, support revenue spread over the 2 years","All revenue is recognized at the end of 2 years","Only the support is revenue; the phone is a gift"],
    answer: 1,
    explain: "Each distinct promise is its own performance obligation. The phone is delivered at a point in time. The support is delivered over time, so its share of the price is recognized gradually over the 24 months." },
  { id: "ba-014", topic: "basics", sub: "Revenue recognition", difficulty: 3, type: "mc",
    prompt: "A store sells a laptop plus a 1-year service plan as a bundle for $1,200. Sold separately, the laptop is $1,000 and the plan is $250. Using relative standalone selling prices, how much revenue is recognized when the laptop is handed over?",
    choices: ["$960","$1,200","$1,000","$950"],
    answer: 0,
    explain: "Total standalone value is $1,000 + $250 = $1,250, and the laptop makes up $1,000 ÷ $1,250 = 80% of it. So the laptop gets 80% × $1,200 = $960, recognized at handover. The plan's $240 is recognized over the year. $950 is what you get by subtracting the plan's full $250 from the bundle price." },
  { id: "ba-015", topic: "basics", sub: "Matching principle", difficulty: 1, type: "mc",
    prompt: "What does the <b>matching principle</b> say?",
    choices: ["Every debit must be matched with a credit","Assets must equal liabilities plus equity","Cash in must match cash out each period","Expenses are recorded in the same period as the revenues they help generate"],
    answer: 3,
    explain: "Matching means costs follow the revenue they helped produce. For example, inventory cost becomes COGS when the item is sold, and a machine's cost is spread out through depreciation. Debits equaling credits is double-entry bookkeeping, a different idea." },
  { id: "ba-016", topic: "basics", sub: "Matching principle", difficulty: 2, type: "mc",
    prompt: "A salesperson earns a $2,000 commission on sales made in January. The commission is paid on February 15. When is the commission <b>expense</b> recorded?",
    choices: ["February","Split evenly between January and February","January","When the customer pays for the goods"],
    answer: 2,
    explain: "The commission was earned because of January's sales, so it's a January expense. At Jan 31 the company records an accrued liability (commissions payable), and February's payment just settles it." },
  { id: "ba-017", topic: "basics", sub: "Capitalize vs expense", difficulty: 2, type: "mc",
    prompt: "Why is a $50,000 delivery truck depreciated over 5 years instead of being expensed entirely in the year it's bought?",
    choices: ["Because tax law forbids expensing it","Because the truck helps generate revenue for 5 years, so its cost is spread over those years (matching)","Because the truck's market value falls exactly 20% per year","Because cash for the truck is paid in installments"],
    answer: 1,
    explain: "The truck produces benefits for several years, so matching says its cost should be spread over those years. That's what depreciation does: $50,000 ÷ 5 = $10,000 of expense per year with straight-line. Depreciation allocates cost. It isn't a measure of market value." },
  { id: "ba-018", topic: "basics", sub: "Capitalize vs expense", difficulty: 2, type: "sort",
    prompt: "For a small delivery business, should each cost be <b>capitalized</b> (recorded as an asset) or <b>expensed</b> right away?",
    buckets: ["Capitalize (asset)","Expense now"],
    items: [
      ["Buying a new delivery van","Capitalize (asset)"],
      ["This month's electricity bill","Expense now"],
      ["Buying a warehouse building","Capitalize (asset)"],
      ["Drivers' wages for the month","Expense now"],
      ["Buying a plot of land for a future depot","Capitalize (asset)"],
      ["A one-day radio advertisement","Expense now"],
      ["A routine oil change on the van","Expense now"],
      ["Routing software licensed for 3 years, paid upfront","Capitalize (asset)"]
    ],
    explain: "Capitalize costs that bring benefits over several future periods: vehicles, buildings, land, and multi-year software. Expense costs whose benefit is used up now, like utilities, wages, a one-time ad, or routine maintenance. Land is capitalized but never depreciated." },
  { id: "ba-019", topic: "basics", sub: "Capitalize vs expense", difficulty: 2, type: "mc",
    prompt: "A bike shop pays $3,000 cash on January 1 for a repair stand expected to last 6 years (no salvage value, straight-line). How much expense for the stand appears on this year's income statement?",
    choices: ["$500","$3,000","$0","$250"],
    answer: 0,
    explain: "The stand is capitalized as PP&E and depreciated: $3,000 ÷ 6 years = $500 per year. The $3,000 cash payment shows up on the cash flow statement as capex (investing), not as an expense. $250 is the per-year figure for a 12-year life." },
  { id: "ba-020", topic: "basics", sub: "Capitalize vs expense", difficulty: 2, type: "tf",
    prompt: "In the year of purchase, capitalizing a long-lived cost (instead of expensing it all at once) makes that year's net income higher.",
    answer: true,
    explain: "If you capitalize, only that year's depreciation hits the income statement instead of the whole cost, so this year's profit is higher. Total expense over the asset's life is the same either way. Capitalizing just spreads it out." },
  { id: "ba-021", topic: "basics", sub: "Capitalize vs expense", difficulty: 3, type: "mc",
    prompt: "A company mistakenly <b>expenses</b> a $10,000 machine that should have been capitalized (5-year life, straight-line, no salvage). Compared with the correct treatment, year-1 <b>pre-tax income</b> is…",
    choices: ["understated by $10,000","understated by $2,000","overstated by $8,000","understated by $8,000"],
    answer: 3,
    explain: "Correct treatment: depreciation of $10,000 ÷ 5 = $2,000. Wrong treatment: a $10,000 expense. The extra $10,000 − $2,000 = $8,000 of expense makes pre-tax income $8,000 too low. At 40% tax, net income is $4,800 too low." },
  { id: "ba-022", topic: "basics", sub: "Accounting equation", difficulty: 1, type: "mc",
    prompt: "Which is the fundamental accounting equation?",
    choices: ["Assets + Liabilities = Equity","Revenue − Expenses = Assets","Assets = Liabilities + Equity","Equity = Assets + Liabilities"],
    answer: 2,
    explain: "Everything a company owns (assets) was paid for either by creditors (liabilities) or by owners (equity). Every transaction keeps A = L + E in balance." },
  { id: "ba-023", topic: "basics", sub: "Accounting equation", difficulty: 1, type: "mc",
    prompt: "A company has total assets of $500,000 and total liabilities of $320,000. What is its shareholders' equity?",
    choices: ["$820,000","$180,000","$320,000","$500,000"],
    answer: 1,
    explain: "Equity = Assets − Liabilities = $500,000 − $320,000 = $180,000. $820,000 comes from adding the two instead of subtracting." },
  { id: "ba-024", topic: "basics", sub: "Accounting equation", difficulty: 1, type: "mc",
    prompt: "A food truck business has $45,000 of liabilities and $70,000 of owners' equity. What are its total assets?",
    choices: ["$115,000","$25,000","$70,000","$45,000"],
    answer: 0,
    explain: "Assets = Liabilities + Equity = $45,000 + $70,000 = $115,000. $25,000 is the difference between the two, which is a common slip." },
  { id: "ba-025", topic: "basics", sub: "Accounting equation", difficulty: 1, type: "mc",
    prompt: "A company borrows $20,000 cash from a bank. How does this affect the accounting equation?",
    choices: ["Assets +$20,000; Equity +$20,000","Liabilities +$20,000; Equity −$20,000","No effect until the loan is repaid","Assets +$20,000; Liabilities +$20,000"],
    answer: 3,
    explain: "Cash (an asset) goes up $20,000, and the loan payable (a liability) goes up $20,000. Equity doesn't change, because borrowing isn't income. The company owes the money back." },
  { id: "ba-026", topic: "basics", sub: "Accounting equation", difficulty: 2, type: "match",
    prompt: "Match each $5,000 transaction to its effect on the accounting equation.",
    pairs: [
      ["Borrow $5,000 from a bank","Assets ↑, Liabilities ↑"],
      ["Repay $5,000 of debt principal","Assets ↓, Liabilities ↓"],
      ["Owner invests $5,000 cash","Assets ↑, Equity ↑"],
      ["Buy $5,000 of equipment with cash","One asset ↑, another asset ↓"],
      ["Pay a $5,000 dividend","Assets ↓, Equity ↓"],
      ["Record $5,000 of wages earned but not yet paid","Liabilities ↑, Equity ↓"]
    ],
    explain: "Every transaction keeps A = L + E balanced. Buying equipment with cash just swaps one asset for another. Unpaid wages are an expense, which lowers retained earnings, and they also create a liability (accrued wages)." },
  { id: "ba-027", topic: "basics", sub: "Equity effects", difficulty: 2, type: "multi",
    prompt: "Which transactions change a company's <b>total shareholders' equity</b>? Select all that apply.",
    choices: ["Earning revenue","Paying a cash dividend","Issuing new shares for cash","Buying equipment with cash","Borrowing from a bank","Incurring rent expense","Collecting an account receivable"],
    answers: [0,1,2,5],
    explain: "Equity changes through net income (revenue raises it, expenses lower it), through dividends (lower it), and through share issuance or buybacks. Buying equipment, borrowing, and collecting A/R only move amounts between assets and liabilities." },
  { id: "ba-028", topic: "basics", sub: "Equity effects", difficulty: 2, type: "tf",
    prompt: "Collecting $1,000 from a customer who already owed you (accounts receivable) increases equity by $1,000.",
    answer: false,
    explain: "The revenue (and the equity increase) was recorded when the sale happened. Collecting it later is an asset swap: Cash +$1,000, A/R −$1,000. Equity doesn't change." },
  { id: "ba-029", topic: "basics", sub: "Equity effects", difficulty: 3, type: "mc",
    prompt: "At the start of the year a company had assets of $100,000 and liabilities of $60,000. During the year it earned net income of $15,000, paid dividends of $5,000, issued $10,000 of new stock, and borrowed $20,000. What is <b>ending equity</b>?",
    choices: ["$80,000","$65,000","$60,000","$50,000"],
    answer: 2,
    explain: "Beginning equity = $100,000 − $60,000 = $40,000. Ending equity = $40,000 + $15,000 NI − $5,000 dividends + $10,000 stock = $60,000. Borrowing raises assets and liabilities but not equity. $80,000 wrongly adds the loan, and $65,000 forgets the dividends." },
  { id: "ba-030", topic: "basics", sub: "Debits & credits", difficulty: 1, type: "mc",
    prompt: "Which type of account normally <b>increases with a debit</b>?",
    choices: ["Revenue","Assets (e.g., Cash)","Accounts payable","Common stock"],
    answer: 1,
    explain: "Assets and expenses increase with debits. Liabilities, equity, and revenue increase with credits. One way to remember it: debits are on the left side of the equation (assets), and credits are on the right (liabilities + equity)." },
  { id: "ba-031", topic: "basics", sub: "Debits & credits", difficulty: 2, type: "sort",
    prompt: "Sort each account by what <b>increases</b> it.",
    buckets: ["A debit increases it","A credit increases it"],
    items: [
      ["Cash","A debit increases it"],
      ["Equipment","A debit increases it"],
      ["Rent expense","A debit increases it"],
      ["Cost of goods sold","A debit increases it"],
      ["Accounts payable","A credit increases it"],
      ["Sales revenue","A credit increases it"],
      ["Common stock","A credit increases it"],
      ["Notes payable (loan)","A credit increases it"]
    ],
    explain: "Debit-normal: assets and expenses (expenses reduce equity, so they sit opposite equity). Credit-normal: liabilities, equity, and revenue (revenue builds equity)." },
  { id: "ba-032", topic: "basics", sub: "Debits & credits", difficulty: 1, type: "mc",
    prompt: "A shop makes a $500 cash sale. Which journal entry records the revenue?",
    choices: ["Debit Cash $500; Credit Revenue $500","Debit Revenue $500; Credit Cash $500","Debit Cash $500; Credit Accounts Receivable $500","Debit Accounts Receivable $500; Credit Revenue $500"],
    answer: 0,
    explain: "Cash (an asset) goes up, so debit it. Revenue goes up, so credit it. Debiting A/R would be right for a credit sale, and debiting cash while crediting A/R is a collection, not a sale." },
  { id: "ba-033", topic: "basics", sub: "Debits & credits", difficulty: 2, type: "mc",
    prompt: "A café buys $200 of cleaning supplies <b>on account</b> (to pay next month). What is the entry?",
    choices: ["Debit Accounts Payable $200; Credit Cash $200","Debit Supplies $200; Credit Cash $200","Debit Cash $200; Credit Supplies $200","Debit Supplies $200; Credit Accounts Payable $200"],
    answer: 3,
    explain: "The café gains an asset (supplies, so debit) and owes the supplier (accounts payable, so credit). No cash moves yet. Next month's payment will be Debit A/P, Credit Cash." },
  { id: "ba-034", topic: "basics", sub: "Debits & credits", difficulty: 1, type: "tf",
    prompt: "In double-entry bookkeeping, total debits must equal total credits in every journal entry.",
    answer: true,
    explain: "Every transaction affects at least two accounts, and the debits always equal the credits. That's what keeps A = L + E in balance." },
  { id: "ba-035", topic: "basics", sub: "Debits & credits", difficulty: 2, type: "tf",
    prompt: "A debit always means an increase to an account.",
    answer: false,
    explain: "Debit just means the left side. It increases assets and expenses but decreases liabilities, equity, and revenue. Paying off a loan, for example, debits (decreases) Notes Payable." },
  { id: "ba-036", topic: "basics", sub: "Debits & credits", difficulty: 2, type: "mc",
    prompt: "Last month a company accrued $1,000 of wages it owed. This month it pays them. What is this month's entry?",
    choices: ["Debit Wages Expense $1,000; Credit Cash $1,000","Debit Cash $1,000; Credit Wages Payable $1,000","Debit Wages Payable $1,000; Credit Cash $1,000","Debit Wages Expense $1,000; Credit Wages Payable $1,000"],
    answer: 2,
    explain: "The expense was already recorded last month when the wages were accrued. Now you just settle the liability: Wages Payable goes down (debit) and Cash goes down (credit). Debiting the expense again would count it twice." },
  { id: "ba-037", topic: "basics", sub: "GAAP vs IFRS", difficulty: 1, type: "mc",
    prompt: "Which accounting framework do U.S. public companies use to file with the SEC?",
    choices: ["IFRS","U.S. GAAP","Tax-basis accounting","Cash-basis accounting"],
    answer: 1,
    explain: "U.S. domestic public companies report under U.S. GAAP, which is set by the FASB. IFRS, set by the IASB, is used in the EU, the UK, and most of the rest of the world." },
  { id: "ba-038", topic: "basics", sub: "GAAP vs IFRS", difficulty: 2, type: "mc",
    prompt: "Which inventory method is allowed under U.S. GAAP but <b>prohibited</b> under IFRS?",
    choices: ["LIFO","FIFO","Weighted average cost","Specific identification"],
    answer: 0,
    explain: "LIFO (last-in, first-out) is allowed under U.S. GAAP but banned under IFRS. FIFO, weighted average, and specific identification are allowed under both." },
  { id: "ba-039", topic: "basics", sub: "GAAP vs IFRS", difficulty: 2, type: "tf",
    prompt: "IFRS allows companies to revalue PP&E upward to fair value, while U.S. GAAP generally does not.",
    answer: true,
    explain: "IFRS offers a revaluation model for PP&E. U.S. GAAP sticks to historical cost less depreciation and only allows write-downs (impairments), never write-ups." },
  { id: "ba-040", topic: "basics", sub: "GAAP vs IFRS", difficulty: 3, type: "mc",
    prompt: "Which statement about classifying <b>interest paid</b> on the cash flow statement is correct?",
    choices: ["Both U.S. GAAP and IFRS require it in financing","U.S. GAAP requires it in investing; IFRS requires operating","It never appears on the cash flow statement","U.S. GAAP requires it in operating; IFRS allows operating or financing"],
    answer: 3,
    explain: "Under U.S. GAAP, interest paid is an operating cash flow (that's the class convention too). IFRS gives a choice: operating or financing. It's a frequent interview question about the differences between the two frameworks." },
  { id: "ba-041", topic: "basics", sub: "SEC filings", difficulty: 1, type: "match",
    prompt: "Match each SEC filing to what it is.",
    pairs: [
      ["10-K","Annual report with audited financial statements"],
      ["10-Q","Quarterly report with unaudited (reviewed) statements"],
      ["8-K","Current report on a major event (e.g., CEO exit, acquisition)"],
      ["Proxy statement (DEF 14A)","Executive pay and items for shareholder vote"],
      ["S-1","Registration statement for an IPO"]
    ],
    explain: "The 10-K is the full annual report and the 10-Q is the quarterly one. The 8-K announces material events within about four business days. Proxies cover voting and executive pay, and the S-1 registers shares for an IPO." },
  { id: "ba-042", topic: "basics", sub: "SEC filings", difficulty: 1, type: "mc",
    prompt: "Which filing contains a public company's <b>audited annual</b> financial statements?",
    choices: ["10-Q","8-K","10-K","Form 4"],
    answer: 2,
    explain: "The 10-K is the annual report, and its financial statements are audited by an independent auditor. 10-Qs are quarterly and only reviewed, not audited. A Form 4 reports insider trades." },
  { id: "ba-043", topic: "basics", sub: "SEC filings", difficulty: 1, type: "mc",
    prompt: "A company's CEO unexpectedly resigns on a Tuesday. Which filing will the company most likely file within about four business days?",
    choices: ["10-K","8-K","10-Q","S-1"],
    answer: 1,
    explain: "The 8-K is the current report for material events between regular filings, such as leadership changes, acquisitions, bankruptcy, or a change of auditor." },
  { id: "ba-044", topic: "basics", sub: "SEC filings", difficulty: 1, type: "tf",
    prompt: "The financial statements in a 10-Q are fully audited.",
    answer: false,
    explain: "10-Q statements are <i>reviewed</i> by the auditor, which is a lighter level of assurance, not audited. Only the annual 10-K statements get a full audit." },
  { id: "ba-045", topic: "basics", sub: "Which statement", difficulty: 1, type: "match",
    prompt: "Match each financial statement to the question it answers.",
    pairs: [
      ["Income statement","Was the company profitable over the period?"],
      ["Balance sheet","What does it own and owe on a specific date?"],
      ["Cash flow statement","Where did cash come from and go during the period?"],
      ["Statement of shareholders' equity","How did equity change (stock issued, dividends, buybacks)?"]
    ],
    explain: "The income statement shows profitability, the balance sheet shows financial position at a moment, the cash flow statement shows the movement of cash, and the equity statement explains changes in each equity account." },
  { id: "ba-046", topic: "basics", sub: "Period vs point in time", difficulty: 1, type: "mc",
    prompt: "Which financial statement is a snapshot at a single <b>point in time</b>?",
    choices: ["Balance sheet","Income statement","Cash flow statement","Statement of shareholders' equity"],
    answer: 0,
    explain: "The balance sheet is dated as of a specific day, such as December 31. The income statement, cash flow statement, and equity statement each cover a span of time, such as a quarter or a year." },
  { id: "ba-047", topic: "basics", sub: "Period vs point in time", difficulty: 1, type: "sort",
    prompt: "Does each item measure activity <b>over a period</b>, or a balance at a <b>point in time</b>?",
    buckets: ["Over a period of time","Point in time (snapshot)"],
    items: [
      ["Revenue for Q3","Over a period of time"],
      ["Net income for the year","Over a period of time"],
      ["Cash from operations for the year","Over a period of time"],
      ["Depreciation expense for the year","Over a period of time"],
      ["Inventory balance on Dec 31","Point in time (snapshot)"],
      ["Cash balance at quarter-end","Point in time (snapshot)"],
      ["Total debt outstanding on June 30","Point in time (snapshot)"],
      ["Accumulated depreciation as of year-end","Point in time (snapshot)"]
    ],
    explain: "Income statement and cash flow items are flows that build up over a period. Balance sheet items are stocks measured on one date. Depreciation <i>expense</i> is a flow, but <i>accumulated</i> depreciation is a balance-sheet balance." },
  { id: "ba-048", topic: "basics", sub: "Period vs point in time", difficulty: 2, type: "mc",
    prompt: "An income statement is headed “For the year ended December 31, 2025,” while the balance sheet says “As of December 31, 2025.” Why the difference?",
    choices: ["The balance sheet is unaudited","They are prepared by different departments","The income statement uses cash accounting","The income statement adds up activity over the whole year; the balance sheet shows balances on one day"],
    answer: 3,
    explain: "The headings tell you the time frame. The income statement measures a flow (a full year of revenue and expenses). The balance sheet measures a stock (what's owned and owed at the close of business on Dec 31)." },
  { id: "ba-049", topic: "basics", sub: "Users of statements", difficulty: 2, type: "match",
    prompt: "Match each user of financial statements to their main question.",
    pairs: [
      ["Bank lender","Can the company make interest and principal payments?"],
      ["Equity investor","How fast will earnings and cash flow grow, and what is the stock worth?"],
      ["Management","How should we price, budget and hire?"],
      ["Tax authority","How much taxable income is owed?"],
      ["Supplier","If we ship on credit, will we get paid?"]
    ],
    explain: "Different users read the same statements for different reasons. Creditors focus on repayment ability, equity investors on growth and value, managers on decisions, governments on taxes, and suppliers on credit risk." },
  { id: "ba-050", topic: "basics", sub: "Going concern", difficulty: 1, type: "mc",
    prompt: "What is the <b>going concern</b> assumption?",
    choices: ["The business will be sold within a year","The business must always be profitable","The business will keep operating for the foreseeable future","Assets are reported at liquidation value"],
    answer: 2,
    explain: "Financial statements assume the company will keep running. That's why assets are carried at cost less depreciation and not at fire-sale liquidation prices." },
  { id: "ba-051", topic: "basics", sub: "Going concern", difficulty: 2, type: "mc",
    prompt: "An auditor adds a “substantial doubt about the ability to continue as a going concern” paragraph to a company's 10-K. What does this signal?",
    choices: ["The company has already filed for bankruptcy","There is serious risk the company may not survive the next year (e.g., it may run out of cash)","The auditor found fraud","The company switched from IFRS to GAAP"],
    answer: 1,
    explain: "A going-concern warning is a red flag that the company may not meet its obligations over roughly the next 12 months, for example because of heavy losses, debt coming due, or low cash. It's a warning, not a bankruptcy filing or a fraud finding." },
  { id: "ba-052", topic: "basics", sub: "Going concern", difficulty: 1, type: "tf",
    prompt: "A going-concern warning from the auditor means the company is legally bankrupt.",
    answer: false,
    explain: "It means there is <i>substantial doubt</i> about survival. Many companies with warnings raise new money or turn around. Bankruptcy is a separate legal process." },
  { id: "ba-053", topic: "basics", sub: "Conservatism", difficulty: 2, type: "mc",
    prompt: "A company is in two lawsuits. In one it will probably <b>lose</b> about $2M; in the other it will probably <b>win</b> about $3M. Under conservative accounting (U.S. GAAP), what is recorded now?",
    choices: ["The probable $2M loss is recorded; the probable $3M gain is not recorded until realized","Both: a $2M loss and a $3M gain","Neither until the cases end","A net $1M gain"],
    answer: 0,
    explain: "Conservatism means losses are recognized when probable and estimable, but gains wait until they're realized. The $2M is accrued as a loss and a liability. The $3M possible gain can only be disclosed." },
  { id: "ba-054", topic: "basics", sub: "Conservatism", difficulty: 2, type: "mc",
    prompt: "A store's inventory cost $50,000. Under U.S. GAAP, what happens if its market value <b>falls</b> to $40,000? And if it instead <b>rises</b> to $60,000?",
    choices: ["Write down to $40,000; write up to $60,000","No change in either case","No write-down; write up to $60,000","Write down to $40,000; no write-up to $60,000"],
    answer: 3,
    explain: "Inventory is carried at the lower of cost or market (net realizable value). A $10,000 drop is written down as an expense now. A rise above cost isn't booked, and the profit only appears when the goods are sold." },
  { id: "ba-055", topic: "basics", sub: "Materiality", difficulty: 1, type: "mc",
    prompt: "A $5 billion company buys a $40 stapler that will last 10 years and simply expenses it. Which principle justifies this?",
    choices: ["Conservatism","Going concern","Materiality","Revenue recognition"],
    answer: 2,
    explain: "Materiality means an amount too small to change any reader's decision doesn't need the strict treatment. Depreciating a $40 stapler over 10 years would cost more effort than it's worth, so it's expensed right away." },
  { id: "ba-056", topic: "basics", sub: "Materiality", difficulty: 2, type: "tf",
    prompt: "Materiality is a fixed dollar threshold (e.g., $10,000) set by the SEC for every company.",
    answer: false,
    explain: "Materiality is a judgment that depends on size and context. $10,000 is material to a food truck but trivial to Apple. Auditors often use rules of thumb, such as a few percent of pre-tax income, but there's no universal dollar amount." },
  { id: "ba-057", topic: "basics", sub: "Historical cost", difficulty: 1, type: "mc",
    prompt: "A company bought land in 1990 for $200,000. It is worth $2 million today. Under U.S. GAAP, what does the balance sheet show for the land?",
    choices: ["$2,000,000","$200,000","$1,100,000 (average)","$0, since land is fully depreciated"],
    answer: 1,
    explain: "Under the historical cost principle, the land stays at its original $200,000 cost. Land is also never depreciated, so it doesn't fall to $0. The $1.8M of appreciation isn't recorded unless the land is sold." },
  { id: "ba-058", topic: "basics", sub: "GAAP principles", difficulty: 2, type: "match",
    prompt: "Match each accounting principle to an example of it in action.",
    pairs: [
      ["Historical cost","Land shown at its 1995 purchase price"],
      ["Conservatism","Book a probable lawsuit loss, but not a probable lawsuit win"],
      ["Materiality","Expense a $30 stapler even though it lasts for years"],
      ["Going concern","Value assets assuming the business keeps operating, not at fire-sale prices"],
      ["Matching","Record sales commissions in the same period as the sales"],
      ["Revenue recognition","Record revenue when the service is delivered, not when the contract is signed"]
    ],
    explain: "These principles work together. Historical cost keeps values objective, conservatism avoids overstating results, materiality keeps the work practical, going concern sets the valuation basis, and matching and revenue recognition decide the timing of income-statement items." },
  { id: "ba-059", topic: "basics", sub: "Matching principle", difficulty: 2, type: "multi",
    prompt: "Which of these are examples of the <b>matching principle</b>? Select all that apply.",
    choices: ["Depreciating a pizza oven over 8 years","Recording December wages as a December expense even though they're paid January 3","Recording the cost of inventory as COGS in the period it is sold","Recording revenue only when cash is collected","Expensing the full cost of a 30-year building in the year it is bought","Estimating warranty expense in the year the products are sold"],
    answers: [0,1,2,5],
    explain: "Matching puts expenses in the period of the revenue they support: depreciation over the asset's useful life, accrued wages, COGS when the goods are sold, and warranty costs when the products are sold. Recording revenue only on cash collection is cash-basis accounting, and expensing a building up front breaks matching." },
  { id: "ba-060", topic: "basics", sub: "SEC filings", difficulty: 1, type: "multi",
    prompt: "Which of these are core financial statements found in a 10-K? Select all that apply.",
    choices: ["Income statement","Balance sheet","Cash flow statement","Statement of shareholders' equity","Earnings call transcript","Analysts' price targets"],
    answers: [0,1,2,3],
    explain: "The 10-K contains the four core statements plus notes, MD&A, and the auditor's report. Earnings call transcripts and analysts' price targets come from outside the filing." },
  { id: "ba-061", topic: "basics", sub: "Accrual vs cash", difficulty: 3, type: "multi",
    prompt: "Under accrual accounting, which of these are <b>December expenses</b> for a company with a December 31 year-end? Select all that apply.",
    choices: ["December's utility bill, paid in January","January's rent, prepaid in December","Wages employees earned in December, paid January 3","Interest that built up on a loan during December, paid in March","The full purchase price of a forklift bought in December","Inventory bought in December that is still unsold at year-end"],
    answers: [0,2,3],
    explain: "Expenses follow when costs are incurred: December's utilities, wages, and interest belong to December even if they're paid later. Prepaid January rent is an asset (a prepaid expense). The forklift is capitalized, and unsold inventory stays an asset until it's sold." },
  { id: "ba-062", topic: "basics", sub: "Revenue recognition", difficulty: 3, type: "multi",
    prompt: "Which situations generally allow revenue to be recognized <b>this period</b> under ASC 606? Select all that apply.",
    choices: ["Goods shipped this period, and the contract says ownership passes when they leave the warehouse","A customer paid a deposit for custom furniture that won't be built until next quarter","A consultant completed half of a 4-month project this period (billed only at the end)","A 2-year service contract was signed, but service starts next period","A gift card was sold, but not yet redeemed","One month of an annual subscription was delivered this period"],
    answers: [0,2,5],
    explain: "Revenue follows delivery. That covers the shipped goods (control passed), the portion of the consulting work completed (earned over time even though it isn't billed yet), and the subscription month delivered. Deposits, unstarted contracts, and unredeemed gift cards are all still deferred revenue." },
  { id: "ba-063", topic: "basics", sub: "SEC filings", difficulty: 2, type: "multi",
    prompt: "Which events would most likely trigger an <b>8-K</b> filing? Select all that apply.",
    choices: ["Completing the acquisition of another company","The CEO unexpectedly departs","Running the ordinary weekly payroll","Filing for bankruptcy","A routine office-supply purchase","Changing the company's outside auditor"],
    answers: [0,1,3,5],
    explain: "8-Ks cover material, unscheduled events that investors need to know about quickly. Ordinary operations like payroll or office supplies don't qualify." },
  { id: "ba-064", topic: "basics", sub: "Accounting equation", difficulty: 3, type: "multi",
    prompt: "Which transactions increase <b>both</b> assets and liabilities? Select all that apply.",
    choices: ["Borrowing $10,000 from a bank","Buying inventory on credit","Receiving a customer's prepayment for a future service","Paying a supplier invoice","Issuing new shares for cash","Buying equipment with cash"],
    answers: [0,1,2],
    explain: "A loan adds cash and debt. Inventory bought on credit adds inventory and A/P. A prepayment adds cash and deferred revenue, a liability until the service is delivered. Paying a supplier lowers both sides, issuing shares raises equity instead of liabilities, and buying equipment with cash is an asset swap." },
  { id: "ba-065", topic: "basics", sub: "Accounting cycle", difficulty: 2, type: "order",
    prompt: "Order the steps that turn a business transaction into financial statements.",
    items: ["A transaction occurs (e.g., a sale)","Record the journal entry (debits and credits)","Post the entry to the general ledger accounts","Prepare an unadjusted trial balance","Make adjusting entries (accruals, depreciation)","Prepare the financial statements"],
    explain: "This is the accounting cycle: journalize, post to the ledger, check that debits equal credits on the trial balance, adjust for accruals and depreciation at period end, and then produce the statements." },
  { id: "ba-066", topic: "basics", sub: "Which statement", difficulty: 1, type: "order",
    prompt: "In a class-style “walk me through” of a transaction, in what order do you go through the statements?",
    items: ["Income statement","Cash flow statement","Balance sheet","Check that Assets = Liabilities + Equity"],
    explain: "Start with the income statement, because net income feeds the CFS. The cash flow statement then gives you the change in cash. The balance sheet picks up cash and retained earnings, and you finish by checking that A = L + E." },
  { id: "ba-067", topic: "basics", sub: "SEC filings", difficulty: 2, type: "order",
    prompt: "For a company with a December 31 fiscal year-end, order these filings from earliest to latest (for fiscal year 2026).",
    items: ["10-Q for Q1 (around May 2026)","10-Q for Q2 (around August 2026)","10-Q for Q3 (around November 2026)","10-K for the full year (around February–March 2027)"],
    explain: "Companies file three 10-Qs a year. There's no Q4 10-Q, because the 10-K covers the full year, and it's filed a couple of months after year-end." },
  { id: "ba-068", topic: "basics", sub: "Equity effects", difficulty: 1, type: "order",
    prompt: "Put the retained earnings roll-forward in order.",
    items: ["Beginning retained earnings","+ Net income","− Dividends","= Ending retained earnings"],
    explain: "Retained earnings are the profits a company has kept over its life. Each period they grow by net income (or shrink with a loss) and drop by dividends paid out to shareholders." },
  { id: "ba-069", topic: "basics", sub: "Accrual vs cash", difficulty: 3, type: "mc",
    prompt: "In 2025 a freelance designer completed $50,000 of work and collected $42,000 of it. She also collected $6,000 in 2025 for work finished in 2024, and received $4,000 of deposits for 2026 projects. What is her 2025 revenue under <b>accrual</b> accounting?",
    choices: ["$50,000","$52,000","$42,000","$56,000"],
    answer: 0,
    explain: "Accrual revenue = work completed in 2025 = $50,000. The 2024 collection was 2024's revenue, and the 2026 deposits are deferred revenue, so neither counts. $52,000 is the cash-basis figure ($42,000 + $6,000 + $4,000)." },
  { id: "ba-070", topic: "basics", sub: "Accrual vs cash", difficulty: 3, type: "mc",
    prompt: "In 2025 a freelance designer completed $50,000 of work and collected $42,000 of it. She also collected $6,000 in 2025 for work finished in 2024, and received $4,000 of deposits for 2026 projects. What is her 2025 revenue under <b>cash-basis</b> accounting?",
    choices: ["$48,000","$50,000","$46,000","$52,000"],
    answer: 3,
    explain: "Cash basis counts every dollar received in 2025: $42,000 + $6,000 + $4,000 = $52,000. That's $2,000 more than the accrual figure of $50,000, which shows how the two methods diverge." },

  // ===================== INCOME STATEMENT =====================
  { id: "is-001", topic: "is", sub: "Line item order", difficulty: 1, type: "order",
    prompt: "Put these income statement subtotals in order from top to bottom.",
    items: ["Revenue","Gross profit","Operating income (EBIT)","Pre-tax income (EBT)","Net income"],
    explain: "Revenue − COGS = Gross profit. Gross profit − operating expenses = Operating income. Operating income − interest = Pre-tax income. Pre-tax income − taxes = Net income, the bottom line." },
  { id: "is-002", topic: "is", sub: "Line item order", difficulty: 2, type: "order",
    prompt: "Order these lines as they appear on a standard multi-step income statement.",
    items: ["Revenue","Cost of goods sold","Gross profit","Selling, general & administrative (SG&A)","Operating income","Interest expense","Income tax expense","Net income"],
    explain: "Direct costs (COGS) come first to give gross profit. Then come operating costs like SG&A to give operating income. Financing costs (interest) and then taxes come last before net income." },
  { id: "is-003", topic: "is", sub: "EBITDA", difficulty: 2, type: "order",
    prompt: "Using the data below (tax rate 40%), order these measures from <b>largest to smallest</b>.",
    table: { headers: ["Item","Amount"], rows: [["Revenue","$1,000"],["COGS (excl. D&A)","$400"],["SG&A (excl. D&A)","$300"],["Depreciation & amortization","$100"],["Interest expense","$50"]] },
    items: ["Revenue","Gross profit","EBITDA","EBIT (operating income)","Pre-tax income","Net income"],
    explain: "Revenue $1,000. Gross profit = $1,000 − $400 = $600. EBITDA = $600 − $300 = $300. EBIT = $300 − $100 D&A = $200. Pre-tax = $200 − $50 = $150. Net income = $150 × (1 − 40%) = $90." },
  { id: "is-004", topic: "is", sub: "EBITDA", difficulty: 2, type: "order",
    prompt: "Order the steps to walk from net income back <b>up</b> to EBITDA.",
    items: ["Start with net income","Add back income tax expense → pre-tax income","Add back interest expense → EBIT","Add back depreciation & amortization → EBITDA"],
    explain: "Reverse the income statement. Undo taxes first, then interest, then D&A, because that's the reverse of the order they were subtracted going down the page." },
  { id: "is-005", topic: "is", sub: "Building an IS", difficulty: 1, type: "order",
    prompt: "You're given a list of a shop's activities for the month. Order the steps to build its income statement.",
    items: ["Identify revenue earned this period (ignore when cash arrives)","Subtract the cost of the goods sold → gross profit","Subtract operating expenses (wages, rent, marketing, depreciation)","Subtract interest expense → pre-tax income","Subtract taxes (e.g., 40%) → net income"],
    explain: "This is the class method for problems like the coffee shop. Along the way, throw out the traps: loans, owner investments, equipment purchases, and collections of old receivables are not revenue or expenses." },
  { id: "is-006", topic: "is", sub: "Revenue", difficulty: 2, type: "order",
    prompt: "Order these top-of-the-income-statement lines.",
    items: ["Gross sales","Less: returns, allowances & discounts","Net revenue (net sales)","Cost of goods sold","Gross profit"],
    explain: "Companies report revenue net of returns and discounts. Gross profit is calculated from <b>net</b> revenue: Net revenue − COGS." },
  { id: "is-007", topic: "is", sub: "Margins", difficulty: 3, type: "order",
    prompt: "A profitable company has positive cash operating expenses, D&A (all reported in operating expenses), interest expense, and taxes, and no non-operating gains. Order its margins from <b>highest to lowest</b>.",
    items: ["Gross margin","EBITDA margin","Operating (EBIT) margin","Pre-tax margin","Net margin"],
    explain: "Each margin uses the same revenue denominator, and each step down subtracts another cost: cash operating expenses, then D&A, then interest, then taxes. So each margin is smaller than the one before." },
  { id: "is-008", topic: "is", sub: "Non-recurring items", difficulty: 3, type: "order",
    prompt: "Order the bottom part of an income statement for a company that sold off a division this year.",
    items: ["Operating income","Interest expense and other income (expense)","Pre-tax income from continuing operations","Income tax expense","Income from continuing operations","Discontinued operations, net of tax","Net income"],
    explain: "Discontinued operations are shown <b>separately, below</b> income from continuing operations, with their own tax effect already netted. That way investors can see what the ongoing business earns." },
  { id: "is-009", topic: "is", sub: "COGS vs OpEx", difficulty: 1, type: "sort",
    prompt: "A bakery's monthly activities: classify each one.",
    buckets: ["COGS","Operating expense","Not on income statement"],
    items: [
      ["Flour, sugar and butter used in pastries sold","COGS"],
      ["Boxes the cakes were sold in","COGS"],
      ["Monthly store rent","Operating expense"],
      ["Instagram ads","Operating expense"],
      ["Cashier wages","Operating expense"],
      ["Buying a new oven","Not on income statement"],
      ["Repaying part of the bank loan's principal","Not on income statement"],
      ["Paying the owners a dividend","Not on income statement"]
    ],
    explain: "COGS covers the direct costs of what was sold: ingredients and packaging. Running costs like rent, marketing, and front-of-house wages are operating expenses. The oven is capitalized (only its depreciation hits the IS). Loan principal and dividends are financing flows, not expenses." },
  { id: "is-010", topic: "is", sub: "COGS vs OpEx", difficulty: 2, type: "sort",
    prompt: "A bike shop's monthly activities: classify each one.",
    buckets: ["COGS","Operating expense","Not on income statement"],
    items: [
      ["Wholesale cost of bikes sold this month","COGS"],
      ["Shipping paid to get bikes delivered to the store (freight-in)","COGS"],
      ["Bikes bought this month still unsold on the floor","Not on income statement"],
      ["Store manager's salary","Operating expense"],
      ["Website hosting","Operating expense"],
      ["A customer's deposit for a bike arriving next month","Not on income statement"],
      ["This month's insurance","Operating expense"]
    ],
    explain: "Only the inventory that was actually <b>sold</b> becomes COGS, and freight-in is part of inventory cost. Unsold bikes are still inventory, an asset. A customer deposit is deferred revenue, a liability, until the bike is delivered." },
  { id: "is-011", topic: "is", sub: "Revenue recognition", difficulty: 2, type: "sort",
    prompt: "A SaaS (software subscription) startup's month: is each item revenue earned this month?",
    buckets: ["Revenue this month","Not revenue this month"],
    items: [
      ["Monthly subscriptions delivered and billed","Revenue this month"],
      ["Usage fees for API calls made this month, billed next month","Revenue this month"],
      ["An onboarding service completed for a new client this month","Revenue this month"],
      ["The 11 future months of an annual plan paid upfront today","Not revenue this month"],
      ["$2M raised from venture capital investors","Not revenue this month"],
      ["Collecting last month's invoices","Not revenue this month"],
      ["A loan from the founder","Not revenue this month"]
    ],
    explain: "Revenue follows delivery. This month's subscriptions, usage, and completed services count even if they're billed later. The prepaid future months are deferred revenue. VC money and loans are financing, and collecting old invoices just converts A/R into cash." },
  { id: "is-012", topic: "is", sub: "Operating income", difficulty: 2, type: "sort",
    prompt: "Is each line subtracted <b>above</b> operating income (an operating cost) or does it appear <b>below</b> operating income?",
    buckets: ["Above operating income","Below operating income"],
    items: [
      ["Research & development","Above operating income"],
      ["Salaries of the sales team","Above operating income"],
      ["Depreciation of office equipment","Above operating income"],
      ["Office rent","Above operating income"],
      ["Interest expense on bonds","Below operating income"],
      ["Interest income on cash balances","Below operating income"],
      ["Income tax expense","Below operating income"]
    ],
    explain: "Operating income (EBIT) reflects the core business, so it includes all operating costs, D&A among them. Interest income and expense depend on how the company is financed, and taxes come last. Those are all below EBIT." },
  { id: "is-013", topic: "is", sub: "EBITDA", difficulty: 2, type: "sort",
    prompt: "When computing EBITDA, which items are subtracted, and which are excluded (added back or left below)?",
    buckets: ["Subtracted in EBITDA","Excluded from EBITDA"],
    items: [
      ["Cost of goods sold","Subtracted in EBITDA"],
      ["SG&A","Subtracted in EBITDA"],
      ["Research & development","Subtracted in EBITDA"],
      ["Depreciation","Excluded from EBITDA"],
      ["Amortization of intangibles","Excluded from EBITDA"],
      ["Interest expense","Excluded from EBITDA"],
      ["Income taxes","Excluded from EBITDA"]
    ],
    explain: "EBITDA = Earnings Before Interest, Taxes, Depreciation and Amortization. Every operating cost except D&A is subtracted, and the four items in the name are left out." },
  { id: "is-014", topic: "is", sub: "Expense or not", difficulty: 3, type: "sort",
    prompt: "A food truck's month: is each item an <b>expense this month</b>?",
    buckets: ["Expense this month","Not an expense this month"],
    items: [
      ["Ingredients and propane used for food sold this month","Expense this month"],
      ["This month's 1/6 share of a 6-month parking permit paid today","Expense this month"],
      ["Employee wages earned this month, paid next month","Expense this month"],
      ["This month's depreciation on the truck","Expense this month"],
      ["The 5 future months of the 6-month permit","Not an expense this month"],
      ["Buying a second food truck","Not an expense this month"],
      ["Paying last month's supplier invoice","Not an expense this month"],
      ["Owner takes $1,000 out for personal use","Not an expense this month"]
    ],
    explain: "Expenses follow when costs are incurred. That includes accrued wages, this month's slice of a prepaid permit, and depreciation. Future months of the permit are a prepaid asset, a new truck is capex, last month's invoice was last month's expense, and an owner draw reduces equity directly." },
  { id: "is-015", topic: "is", sub: "IS vs BS", difficulty: 1, type: "sort",
    prompt: "Does each item appear on the <b>income statement</b> or the <b>balance sheet</b>?",
    buckets: ["Income statement","Balance sheet"],
    items: [
      ["Revenue","Income statement"],
      ["Cost of goods sold","Income statement"],
      ["Interest expense","Income statement"],
      ["Depreciation expense","Income statement"],
      ["Accounts receivable","Balance sheet"],
      ["Inventory","Balance sheet"],
      ["Retained earnings","Balance sheet"],
      ["Accumulated depreciation","Balance sheet"]
    ],
    explain: "The income statement holds revenues and expenses for a period. The balance sheet holds assets, liabilities, and equity at a point in time. Inventory turns into COGS when it's sold, and depreciation expense builds up in accumulated depreciation." },
  { id: "is-016", topic: "is", sub: "Non-recurring items", difficulty: 2, type: "sort",
    prompt: "Analysts often adjust earnings for one-time items. Classify each line.",
    buckets: ["Recurring","Non-recurring (often adjusted out)"],
    items: [
      ["Monthly rent","Recurring"],
      ["Employee salaries","Recurring"],
      ["Cost of goods sold","Recurring"],
      ["Restructuring charge for closing a plant","Non-recurring (often adjusted out)"],
      ["One-time lawsuit settlement","Non-recurring (often adjusted out)"],
      ["Goodwill impairment","Non-recurring (often adjusted out)"],
      ["Gain on selling the old headquarters building","Non-recurring (often adjusted out)"]
    ],
    explain: "Recurring costs show up every period and reflect the ongoing business. Restructurings, settlements, impairments, and one-off gains distort a single year, so analysts usually remove them, after tax, to get normalized or adjusted earnings." },
  { id: "is-017", topic: "is", sub: "Non-cash expenses", difficulty: 2, type: "sort",
    prompt: "Classify each expense as cash or non-cash in the period it is recorded.",
    buckets: ["Cash expense","Non-cash expense"],
    items: [
      ["Wages paid in cash this month","Cash expense"],
      ["Rent paid this month","Cash expense"],
      ["Cash interest on a loan","Cash expense"],
      ["Depreciation","Non-cash expense"],
      ["Amortization of a patent","Non-cash expense"],
      ["Stock-based compensation","Non-cash expense"],
      ["Inventory write-down","Non-cash expense"],
      ["PIK (paid-in-kind) interest","Non-cash expense"]
    ],
    explain: "Non-cash expenses lower net income without spending cash this period, so the indirect cash flow statement adds them back. PIK interest is added to the loan balance instead of being paid, and SBC is paid in stock." },
  { id: "is-018", topic: "is", sub: "COGS vs OpEx", difficulty: 3, type: "sort",
    prompt: "For a typical SaaS company, classify each cost as cost of revenue (COGS) or an operating expense.",
    buckets: ["Cost of revenue (COGS)","Operating expense"],
    items: [
      ["Cloud hosting that runs the customer-facing product","Cost of revenue (COGS)"],
      ["Customer support team","Cost of revenue (COGS)"],
      ["Payment-processing fees on subscriptions","Cost of revenue (COGS)"],
      ["Sales commissions","Operating expense"],
      ["Engineers building new features (R&D)","Operating expense"],
      ["Headquarters office rent","Operating expense"],
      ["Marketing campaigns","Operating expense"]
    ],
    explain: "A SaaS company's cost of revenue is what it takes to deliver the service it has already sold: hosting, support, and processing fees. Building the next product (R&D), winning new customers (S&M), and running the company (G&A) are operating expenses. That's why SaaS gross margins are often 75–85%." },
  { id: "is-019", topic: "is", sub: "Line items", difficulty: 1, type: "match",
    prompt: "Match each income statement line to its meaning.",
    pairs: [
      ["Revenue","Value of goods/services delivered to customers in the period"],
      ["Cost of goods sold","Direct cost of the products or services that were sold"],
      ["Gross profit","Revenue minus COGS"],
      ["Operating income","Profit from core operations, before interest and taxes"],
      ["Net income","Bottom-line profit after all expenses, interest and taxes"]
    ],
    explain: "Each subtotal peels away another layer of cost. Gross profit measures product economics, operating income measures the whole operation, and net income is what's left for shareholders." },
  { id: "is-020", topic: "is", sub: "Formulas", difficulty: 2, type: "match",
    prompt: "Match each metric to its formula.",
    pairs: [
      ["Gross margin","Gross profit ÷ Revenue"],
      ["Operating margin","Operating income ÷ Revenue"],
      ["Net margin","Net income ÷ Revenue"],
      ["EBITDA","Operating income + D&A"],
      ["Basic EPS","(Net income − preferred dividends) ÷ weighted avg. shares"]
    ],
    explain: "Margins divide a profit level by revenue. EBITDA adds non-cash D&A back to EBIT. EPS spreads the profit available to common shareholders across the average number of shares outstanding." },
  { id: "is-021", topic: "is", sub: "COGS vs OpEx", difficulty: 2, type: "match",
    prompt: "Match each cost to the income statement line where it usually belongs.",
    pairs: [
      ["Salaries of sales reps","Selling / sales & marketing"],
      ["CFO's salary and accounting software","General & administrative"],
      ["Engineers designing next year's product","Research & development"],
      ["Raw materials in the units sold","Cost of goods sold"],
      ["Interest on a term loan","Interest expense (below EBIT)"],
      ["Wear and tear on delivery vans","Depreciation"]
    ],
    explain: "COGS holds the direct product costs. Sales & marketing, G&A, R&D, and depreciation are operating expenses. Interest is a financing cost that appears below operating income." },
  { id: "is-022", topic: "is", sub: "COGS vs OpEx", difficulty: 1, type: "match",
    prompt: "Match each business to a typical item in its cost of goods (or services) sold.",
    pairs: [
      ["Coffee shop","Beans, milk and cups"],
      ["SaaS company","Cloud hosting and customer support"],
      ["Car dealership","Wholesale cost of the cars sold"],
      ["Restaurant","Food and beverage ingredients"],
      ["Furniture maker","Wood, hardware and factory labor"]
    ],
    explain: "COGS is whatever directly goes into delivering the product or service sold. It looks different in every industry, but the rule is always the same: it varies with what was sold." },
  { id: "is-023", topic: "is", sub: "Non-recurring items", difficulty: 2, type: "match",
    prompt: "Match each unusual income statement item to its description.",
    pairs: [
      ["Restructuring charge","Severance and costs of closing facilities"],
      ["Impairment","Write-down when an asset's value falls below its carrying value"],
      ["Discontinued operations","Results of a segment that was sold or shut down, shown net of tax"],
      ["Gain on sale of asset","Sale price above the asset's net book value"],
      ["Litigation settlement","One-time payment to resolve a lawsuit"]
    ],
    explain: "These items are real, but they're usually not part of the ongoing run-rate of the business. Analysts often strip them out (after tax) to judge sustainable earnings." },
  { id: "is-024", topic: "is", sub: "Building an IS", difficulty: 3, type: "match",
    prompt: "Using the data below (tax rate 40%), match each subtotal to its value.",
    table: { headers: ["Item","Amount"], rows: [["Revenue","$2,000"],["COGS","$800"],["SG&A (excl. D&A)","$500"],["Depreciation & amortization","$200"],["Interest expense","$100"]] },
    pairs: [
      ["Gross profit","$1,200"],
      ["EBITDA","$700"],
      ["Operating income (EBIT)","$500"],
      ["Pre-tax income","$400"],
      ["Net income","$240"]
    ],
    explain: "GP = $2,000 − $800 = $1,200. EBITDA = $1,200 − $500 = $700. EBIT = $700 − $200 = $500. Pre-tax = $500 − $100 = $400. Tax = 40% × $400 = $160, so NI = $240." },
  { id: "is-025", topic: "is", sub: "Line items", difficulty: 1, type: "match",
    prompt: "Match each abbreviation to what it stands for.",
    pairs: [
      ["EBIT","Earnings before interest and taxes"],
      ["EBITDA","Earnings before interest, taxes, depreciation & amortization"],
      ["EBT","Earnings before taxes (pre-tax income)"],
      ["EPS","Earnings per share"],
      ["SG&A","Selling, general & administrative expenses"],
      ["COGS","Cost of goods sold"]
    ],
    explain: "In finance, “earnings” means profit. Each abbreviation names exactly which costs have <b>not</b> been subtracted yet." },
  { id: "is-026", topic: "is", sub: "Margins", difficulty: 2, type: "match",
    prompt: "A company has revenue of $5,000, gross profit of $2,000, EBITDA of $1,000, operating income of $750 and net income of $300. Match each metric to its value.",
    pairs: [
      ["Gross margin","40%"],
      ["EBITDA margin","20%"],
      ["Operating margin","15%"],
      ["Net margin","6%"],
      ["COGS as % of revenue","60%"]
    ],
    explain: "Divide each profit level by $5,000 of revenue: $2,000 → 40%, $1,000 → 20%, $750 → 15%, and $300 → 6%. COGS = $5,000 − $2,000 = $3,000, which is 60% of revenue (always 100% − gross margin)." },
  { id: "is-027", topic: "is", sub: "Traps", difficulty: 3, type: "match",
    prompt: "None of these is revenue or an expense. Match each one to where it actually shows up.",
    pairs: [
      ["Taking out a bank loan","Debt liability on the BS; CFF inflow"],
      ["Buying equipment","PP&E on the BS; depreciated over time"],
      ["Paying a dividend","Reduces retained earnings directly; CFF outflow"],
      ["Collecting accounts receivable","Cash ↑, A/R ↓; no new revenue"],
      ["Prepaying a year of rent","Prepaid expense asset, expensed month by month"],
      ["Owner invests cash","Common stock / APIC ↑; CFF inflow"]
    ],
    explain: "These are the classic traps in “build the income statement” problems. Each one moves cash or the balance sheet without being revenue or an expense in that period. Only the depreciation or monthly rent portions eventually hit the IS." },
  { id: "is-028", topic: "is", sub: "Net income vs cash", difficulty: 1, type: "tf",
    prompt: "A company's net income for the year equals the cash it generated that year.",
    answer: false,
    explain: "Accrual accounting records revenue and expenses when they're earned or incurred, not when cash moves. Credit sales, depreciation, prepaid costs, and capex all make net income and cash differ, which is why the cash flow statement exists." },
  { id: "is-029", topic: "is", sub: "D&A", difficulty: 1, type: "tf",
    prompt: "Depreciation is a non-cash expense.",
    answer: true,
    explain: "The cash left when the asset was bought (capex). Depreciation just spreads that cost over the asset's useful life, so it reduces net income without any new cash going out." },
  { id: "is-030", topic: "is", sub: "Traps", difficulty: 1, type: "tf",
    prompt: "Dividends paid to shareholders are recorded as an expense on the income statement.",
    answer: false,
    explain: "Dividends are a distribution of profit, not a cost of earning it. They reduce retained earnings directly and appear as a CFF outflow. Net income is unaffected." },
  { id: "is-031", topic: "is", sub: "Gross profit", difficulty: 2, type: "tf",
    prompt: "Gross profit can be negative.",
    answer: true,
    explain: "If COGS exceeds revenue, for example when selling below cost or after a big inventory write-down in COGS, gross profit is negative. Early-stage companies sometimes have negative gross margins." },
  { id: "is-032", topic: "is", sub: "EBITDA", difficulty: 1, type: "tf",
    prompt: "EBITDA is an official GAAP line item that every company must report on its income statement.",
    answer: false,
    explain: "EBITDA is a <b>non-GAAP</b> metric. Companies often disclose it, and analysts calculate it as EBIT + D&A, but it isn't a required GAAP line." },
  { id: "is-033", topic: "is", sub: "Interest", difficulty: 1, type: "tf",
    prompt: "Repaying $10,000 of loan principal reduces net income by $10,000.",
    answer: false,
    explain: "Principal repayment just shrinks a liability and cash (a CFF outflow). Only the <b>interest</b> on the loan is an expense on the income statement." },
  { id: "is-034", topic: "is", sub: "Interest", difficulty: 1, type: "tf",
    prompt: "Interest expense is subtracted after operating income to get pre-tax income.",
    answer: true,
    explain: "Interest is a financing cost, not an operating cost, so it sits below EBIT: EBIT − net interest expense = pre-tax income (EBT)." },
  { id: "is-035", topic: "is", sub: "Net income vs cash", difficulty: 2, type: "tf",
    prompt: "A company can report positive net income in a year when its cash balance falls.",
    answer: true,
    explain: "Profit isn't cash. A growing company can be profitable while cash falls, for example by selling on credit (A/R rises), building inventory, buying equipment, or repaying debt." },
  { id: "is-036", topic: "is", sub: "EPS", difficulty: 2, type: "tf",
    prompt: "For a profitable company, diluted EPS is always less than or equal to basic EPS.",
    answer: true,
    explain: "Diluted EPS adds shares from options, RSUs, and convertibles to the denominator, and only when they're dilutive. Anti-dilutive securities that would raise EPS are left out, so diluted EPS ≤ basic EPS." },
  { id: "is-037", topic: "is", sub: "Gains & losses", difficulty: 3, type: "tf",
    prompt: "A company sells equipment with a net book value of $100 for $150. The income statement shows $150 of revenue.",
    answer: false,
    explain: "Selling equipment isn't the company's normal business, so it isn't revenue. The IS shows only the <b>gain</b> of $150 − $100 = $50 (NI +$30 at 40% tax). The $150 of proceeds appears in CFI." },
  { id: "is-038", topic: "is", sub: "COGS", difficulty: 1, type: "tf",
    prompt: "When a store buys inventory, the cost is expensed immediately on the income statement.",
    answer: false,
    explain: "Inventory is an asset until it's sold. Its cost moves to COGS only when the goods are sold, which is matching in action." },
  { id: "is-039", topic: "is", sub: "Revenue", difficulty: 2, type: "tf",
    prompt: "Sales tax a store collects from customers on behalf of the state counts as the store's revenue.",
    answer: false,
    explain: "The store is only a collector. The sales tax belongs to the government, so it's recorded as a liability (sales tax payable) until it's remitted. It isn't revenue." },
  { id: "is-040", topic: "is", sub: "Taxes", difficulty: 2, type: "tf",
    prompt: "At a 40% tax rate, an extra $100 of pre-tax expense reduces net income by $60.",
    answer: true,
    explain: "The expense lowers taxable income by $100, which saves 40% × $100 = $40 of tax. Net effect: −$100 + $40 = −$60, or $100 × (1 − 0.40)." },
  { id: "is-041", topic: "is", sub: "SBC", difficulty: 2, type: "tf",
    prompt: "Stock-based compensation is recorded as an expense on the income statement even though no cash is paid.",
    answer: true,
    explain: "Employees are paid in equity instead of cash, but it's still compensation for their work, so it's expensed (usually within COGS, R&D, S&M, or G&A). On the CFS it's added back as a non-cash expense." },
  { id: "is-042", topic: "is", sub: "D&A", difficulty: 1, type: "tf",
    prompt: "Depreciation applies to tangible assets like machines, while amortization applies to intangible assets like patents.",
    answer: true,
    explain: "Both spread an asset's cost over its useful life. Depreciation is for physical PP&E (land excluded), and amortization is for finite-lived intangibles such as patents, software, and customer lists." },
  { id: "is-043", topic: "is", sub: "EBITDA", difficulty: 3, type: "tf",
    prompt: "A company with a net loss can still have positive EBITDA.",
    answer: true,
    explain: "EBITDA leaves out interest, taxes, and D&A. A capital-heavy or highly indebted company can have big D&A and interest costs that push net income negative while EBITDA stays positive. Example: EBITDA $50, D&A $40, interest $30 → pre-tax −$20." },
  { id: "is-044", topic: "is", sub: "Revenue recognition", difficulty: 2, type: "tf",
    prompt: "A caterer receives a $500 deposit today for an event next month. Under accrual accounting, it records $500 of revenue today.",
    answer: false,
    explain: "Nothing has been delivered yet, so the $500 is deferred (unearned) revenue, a liability. It becomes revenue next month when the event is catered. Today: Cash +$500, Deferred revenue +$500." },
  { id: "is-045", topic: "is", sub: "IS basics", difficulty: 1, type: "mc",
    prompt: "What does the income statement primarily show?",
    choices: ["What a company owns and owes on one date","Where the company's cash came from and went","A company's revenues, expenses and profit over a period of time","The company's share price history"],
    answer: 2,
    explain: "The income statement (P&L) covers a period, such as a quarter or a year, and shows whether the company earned a profit. The balance sheet is the snapshot, and the CFS tracks cash." },
  { id: "is-046", topic: "is", sub: "COGS vs OpEx", difficulty: 1, type: "mc",
    prompt: "Which of the following is <b>not</b> an operating expense?",
    choices: ["Office rent","Interest expense on a loan","Marketing team salaries","Research & development"],
    answer: 1,
    explain: "Interest is a financing cost recorded below operating income. Rent, marketing salaries, and R&D are all costs of running the business, so they sit in operating expenses." },
  { id: "is-047", topic: "is", sub: "Gross profit", difficulty: 1, type: "mc",
    prompt: "A shoe store has revenue of $80,000 and cost of goods sold of $30,000. What is its gross profit?",
    choices: ["$50,000","$110,000","$80,000","$30,000"],
    answer: 0,
    explain: "Gross profit = Revenue − COGS = $80,000 − $30,000 = $50,000. That's a 62.5% gross margin ($50,000 ÷ $80,000)." },
  { id: "is-048", topic: "is", sub: "Building an IS", difficulty: 2, type: "mc",
    prompt: "A bakery's activities for the month are below (tax rate 40%; ignore depreciation this month). What is its <b>gross profit</b>?",
    table: { headers: ["Activity","Amount"], rows: [["Bread & pastry sales","$30,000"],["Ingredients used in goods sold","$10,500"],["Staff wages","$8,000"],["Rent","$3,000"],["Bought a new mixer (5-year life)","$4,000"],["Bank loan received","$10,000"],["Owner contributed cash","$5,000"]] },
    choices: ["$15,500","$11,500","$24,500","$19,500"],
    answer: 3,
    explain: "Gross profit = Sales − COGS = $30,000 − $10,500 = $19,500. The mixer is capitalized, not COGS ($15,500 wrongly subtracts it). Wages are an operating expense ($11,500 subtracts them too early), and the owner's cash isn't sales ($24,500 counts it)." },
  { id: "is-049", topic: "is", sub: "Building an IS", difficulty: 3, type: "mc",
    prompt: "A bakery's activities for the month are below (tax rate 40%; ignore depreciation this month). What is its <b>net income</b>?",
    table: { headers: ["Activity","Amount"], rows: [["Bread & pastry sales","$30,000"],["Ingredients used in goods sold","$10,500"],["Staff wages","$8,000"],["Rent","$3,000"],["Bought a new mixer (5-year life)","$4,000"],["Bank loan received","$10,000"],["Owner contributed cash","$5,000"]] },
    choices: ["$8,500","$2,700","$5,100","$8,100"],
    answer: 2,
    explain: "GP $19,500 − OpEx ($8,000 wages + $3,000 rent) = pre-tax $8,500. Tax = 40% × $8,500 = $3,400, so NI = $5,100. $8,500 forgets taxes. $2,700 expenses the mixer (pre-tax $4,500 × 0.6). $8,100 treats the owner's $5,000 as revenue (pre-tax $13,500 × 0.6). The loan is never revenue." },
  { id: "is-050", topic: "is", sub: "Margins", difficulty: 2, type: "mc",
    prompt: "The bakery had sales of $30,000, gross profit of $19,500, pre-tax income of $8,500 and net income of $5,100 (40% tax). What are its gross and net margins?",
    choices: ["65% gross; 28.3% net","65% gross; 17% net","35% gross; 17% net","70% gross; 20% net"],
    answer: 1,
    explain: "Gross margin = $19,500 ÷ $30,000 = 65%. Net margin = $5,100 ÷ $30,000 = 17%. 28.3% is the pre-tax margin ($8,500 ÷ $30,000), and 35% is COGS as a share of sales." },
  { id: "is-051", topic: "is", sub: "Building an IS", difficulty: 3, type: "mc",
    prompt: "A bike shop's month is below (tax rate 40%). Repair labor is done by staff already included in wages, and no parts were used. What is <b>net income</b>?",
    table: { headers: ["Activity","Detail"], rows: [["Bought 60 bikes for inventory","$550 each"],["Sold 40 bikes","$900 each"],["Repair service revenue","$4,000"],["Staff wages","$6,000"],["Rent","$2,500"],["Depreciation on tools","$500"],["Interest on bank loan","$1,000"]] },
    choices: ["$4,800","−$1,800","$8,000","$5,400"],
    answer: 0,
    explain: "Revenue = 40 × $900 + $4,000 = $40,000. COGS covers only the bikes <b>sold</b>: 40 × $550 = $22,000, so GP = $18,000. OpEx = $6,000 + $2,500 + $500 = $9,000 → EBIT $9,000 → pre-tax $8,000 → tax $3,200 → NI $4,800. −$1,800 expenses all 60 bikes, $8,000 forgets tax, and $5,400 forgets interest." },
  { id: "is-052", topic: "is", sub: "Operating income", difficulty: 2, type: "mc",
    prompt: "A bike shop sold 40 bikes at $900 (each cost $550) and earned $4,000 of repair revenue. Expenses: wages $6,000, rent $2,500, depreciation $500, interest $1,000. What is <b>operating income (EBIT)</b>?",
    choices: ["$8,000","$9,500","$18,000","$9,000"],
    answer: 3,
    explain: "Revenue $40,000 − COGS $22,000 = GP $18,000. EBIT = $18,000 − ($6,000 + $2,500 + $500) = $9,000. Interest comes <b>after</b> EBIT ($8,000 wrongly subtracts it), and depreciation is an operating expense ($9,500 leaves it out)." },
  { id: "is-053", topic: "is", sub: "Revenue recognition", difficulty: 2, type: "mc",
    prompt: "On July 1 a SaaS startup collects $120,000 upfront for 12-month contracts. Its fiscal year ends December 31. How much of this is revenue for the year?",
    choices: ["$120,000","$0","$60,000","$10,000"],
    answer: 2,
    explain: "Six months of service (July–December) were delivered: $120,000 × 6/12 = $60,000. The other $60,000 is still deferred revenue at year-end. $10,000 is just one month's worth." },
  { id: "is-054", topic: "is", sub: "Gross profit", difficulty: 2, type: "mc",
    prompt: "A SaaS company reports the figures below. What is its <b>gross margin</b>?",
    table: { headers: ["Item","Amount"], rows: [["Subscription revenue","$500,000"],["Cloud hosting","$75,000"],["Customer support","$25,000"],["Sales & marketing","$200,000"],["R&D","$150,000"],["G&A","$50,000"]] },
    choices: ["85%","80%","20%","0%"],
    answer: 1,
    explain: "Cost of revenue = hosting + support = $100,000, so GP = $400,000 and gross margin = $400,000 ÷ $500,000 = 80%. 85% leaves out support. 0% is the <b>operating</b> margin: $400,000 − $400,000 of OpEx = $0." },
  { id: "is-055", topic: "is", sub: "Building an IS", difficulty: 3, type: "mc",
    prompt: "A food truck's month is below (tax rate 40%). What is <b>net income</b>?",
    table: { headers: ["Activity","Amount"], rows: [["Cash sales of food","$18,000"],["Catering job done, invoiced (paid next month)","$2,000"],["Food & packaging used in sales","$6,000"],["Extra ingredients bought, still unused","$1,500"],["Wages","$5,000"],["Truck depreciation","$400"],["Paid a 12-month permit upfront","$1,200"],["Fuel & propane","$600"],["Collected last month's catering invoice","$1,000"]] },
    choices: ["$4,740","$4,080","$3,540","$5,340"],
    answer: 0,
    explain: "Revenue = $18,000 + $2,000 = $20,000. COGS = $6,000 (unused ingredients stay in inventory), so GP = $14,000. OpEx = $5,000 + $400 + $100 (1/12 of the permit) + $600 = $6,100. Pre-tax $7,900 → tax $3,160 → NI $4,740. $4,080 expenses the whole permit, $3,540 ignores the credit sale, and $5,340 counts the old collection as revenue." },
  { id: "is-056", topic: "is", sub: "Revenue vs cash", difficulty: 2, type: "mc",
    prompt: "This month a food truck made $18,000 of cash sales, completed a $2,000 catering job that will be paid next month, and collected $1,000 for a catering job done last month. What is this month's <b>revenue</b>?",
    choices: ["$18,000","$21,000","$19,000","$20,000"],
    answer: 3,
    explain: "Revenue = what was earned this month = $18,000 + $2,000 = $20,000. The $1,000 collection was last month's revenue, and receiving it now only turns A/R into cash. $19,000 is the cash received ($18,000 + $1,000)." },
  { id: "is-057", topic: "is", sub: "EBITDA", difficulty: 1, type: "mc",
    prompt: "Which formula gives EBITDA?",
    choices: ["Net income + D&A","Revenue − COGS","Operating income (EBIT) + depreciation & amortization","Pre-tax income − D&A"],
    answer: 2,
    explain: "EBITDA = EBIT + D&A. It's also net income + taxes + interest + D&A. Net income + D&A alone forgets to add back interest and taxes." },
  { id: "is-058", topic: "is", sub: "EBITDA", difficulty: 2, type: "mc",
    prompt: "A company reports net income of $60, income tax expense of $40, interest expense of $20, and D&A of $30. What is its EBITDA?",
    choices: ["$120","$150","$90","$130"],
    answer: 1,
    explain: "EBIT = $60 + $40 + $20 = $120. EBITDA = $120 + $30 = $150. $120 is EBIT, and $90 is net income + D&A (it misses taxes and interest)." },
  { id: "is-059", topic: "is", sub: "EBITDA", difficulty: 2, type: "mc",
    prompt: "Why do analysts often use EBITDA to compare companies?",
    choices: ["It removes the effects of financing (interest), taxes, and accounting choices about depreciation, so core operations are easier to compare","It equals the cash a company keeps after all costs","It is required by GAAP","It includes capital expenditures"],
    answer: 0,
    explain: "EBITDA strips out capital structure, tax situation, and D&A policy, so two businesses with different debt loads or asset ages can be compared more directly. It's a rough proxy for operating cash flow, but it isn't cash." },
  { id: "is-060", topic: "is", sub: "EBITDA", difficulty: 3, type: "mc",
    prompt: "What is the biggest criticism of using EBITDA as a measure of cash generation?",
    choices: ["It subtracts too many non-cash items","It double-counts revenue","It can never be negative","It ignores capital expenditures, working capital needs, interest and taxes, all of which take real cash"],
    answer: 3,
    explain: "A capital-heavy business may need to spend most of its EBITDA replacing equipment, and it still has to pay interest and taxes. That's why investors also look at free cash flow (CFO − capex)." },
  { id: "is-061", topic: "is", sub: "D&A", difficulty: 1, type: "mc",
    prompt: "Where does depreciation typically appear on the income statement?",
    choices: ["Below net income","Below interest expense, with taxes","Above operating income: embedded in COGS/OpEx or shown as its own line","It never appears on the income statement"],
    answer: 2,
    explain: "Depreciation is an operating expense. Factory equipment depreciation often sits inside COGS, and office equipment depreciation inside SG&A, or the company shows a separate D&A line. Either way it's subtracted before EBIT." },
  { id: "is-062", topic: "is", sub: "D&A", difficulty: 1, type: "mc",
    prompt: "A pizzeria buys an oven for $24,000 with an 8-year useful life and no salvage value. What is the annual straight-line depreciation?",
    choices: ["$24,000","$3,000","$2,000","$4,000"],
    answer: 1,
    explain: "Straight-line depreciation = (Cost − Salvage) ÷ Useful life = ($24,000 − $0) ÷ 8 = $3,000 per year. $2,000 would be a 12-year life, and $4,000 a 6-year life." },
  { id: "is-063", topic: "is", sub: "D&A", difficulty: 2, type: "mc",
    prompt: "A company's depreciation expense rises by $1,000. With a 40% tax rate, how does net income change?",
    choices: ["−$600","−$1,000","−$400","No change"],
    answer: 0,
    explain: "Pre-tax income falls $1,000, and taxes fall 40% × $1,000 = $400, so NI falls $600. Cash actually goes <b>up</b> $400 from the tax savings, because depreciation itself isn't a cash cost." },
  { id: "is-064", topic: "is", sub: "Interest", difficulty: 2, type: "mc",
    prompt: "A company had a $500,000 loan at 6% interest all year and repaid $50,000 of principal on December 31. What is its <b>interest expense</b> on the income statement for the year?",
    choices: ["$80,000","$50,000","$27,000","$30,000"],
    answer: 3,
    explain: "The full $500,000 was outstanding all year: 6% × $500,000 = $30,000. The $50,000 principal repayment is a CFF outflow, not an expense ($80,000 wrongly adds it). $27,000 applies 6% to $450,000 as if the repayment happened on January 1." },
  { id: "is-065", topic: "is", sub: "Taxes", difficulty: 1, type: "mc",
    prompt: "A company has pre-tax income of $250,000 and a 40% tax rate. What is its net income?",
    choices: ["$100,000","$250,000","$150,000","$210,000"],
    answer: 2,
    explain: "Tax = 40% × $250,000 = $100,000. Net income = $250,000 − $100,000 = $150,000, or $250,000 × (1 − 0.40). $100,000 is the tax itself, not net income." },
  { id: "is-066", topic: "is", sub: "Taxes", difficulty: 2, type: "mc",
    prompt: "A startup has a pre-tax <b>loss</b> of $50,000. Assume a 40% tax rate and that it records the full tax benefit. What is net income?",
    choices: ["−$50,000","−$30,000","−$70,000","−$20,000"],
    answer: 1,
    explain: "A loss creates a tax benefit of 40% × $50,000 = $20,000, so NI = −$50,000 + $20,000 = −$30,000. −$70,000 wrongly adds tax on top of the loss, and −$20,000 confuses the benefit with net income." },
  { id: "is-067", topic: "is", sub: "EPS", difficulty: 1, type: "mc",
    prompt: "Which is the formula for <b>basic</b> EPS?",
    choices: ["(Net income − preferred dividends) ÷ weighted average common shares outstanding","Net income ÷ shares outstanding at year-end, including options","Revenue ÷ shares outstanding","(Net income + dividends) ÷ shares outstanding"],
    answer: 0,
    explain: "Basic EPS uses the profit available to <b>common</b> shareholders (after preferred dividends), divided by the weighted average number of common shares during the period. Including options is what diluted EPS does." },
  { id: "is-068", topic: "is", sub: "EPS", difficulty: 3, type: "mc",
    prompt: "A company earned net income of $12M and paid $2M of preferred dividends. It began the year with 4M common shares and issued 2M more on July 1. What is <b>basic EPS</b>?",
    choices: ["$1.67","$2.40","$2.50","$2.00"],
    answer: 3,
    explain: "Weighted shares = 4M + 2M × (6/12) = 5M. Earnings to common = $12M − $2M = $10M. EPS = $10M ÷ 5M = $2.00. $1.67 uses year-end shares (6M), $2.40 forgets preferred dividends ($12M ÷ 5M), and $2.50 uses beginning shares (4M)." },
  { id: "is-069", topic: "is", sub: "EPS", difficulty: 2, type: "mc",
    prompt: "A company has net income of $9M and 3M basic weighted shares. It has in-the-money options on 1M shares; the treasury stock method says they add a net 0.6M shares. What is <b>diluted EPS</b>?",
    choices: ["$3.00","$2.50","$2.25"],
    answer: 1,
    explain: "Diluted shares = 3M + 0.6M = 3.6M, so diluted EPS = $9M ÷ 3.6M = $2.50. $3.00 is basic EPS. $2.25 adds the gross 1M option shares and ignores the buyback the treasury stock method assumes using the exercise proceeds." },
  { id: "is-070", topic: "is", sub: "EPS", difficulty: 1, type: "mc",
    prompt: "What does <b>diluted</b> EPS show that basic EPS does not?",
    choices: ["EPS before taxes","EPS if all dilutive options, RSUs and convertible securities turned into common shares","EPS after paying dividends","EPS in a foreign currency"],
    answer: 1,
    explain: "Diluted EPS is a what-if: it adds the potential shares from options, warrants, RSUs, and convertibles, as long as they're dilutive. That gives a more conservative per-share profit figure." },
  { id: "is-071", topic: "is", sub: "Non-recurring items", difficulty: 2, type: "mc",
    prompt: "Why do analysts typically adjust out a one-time restructuring charge when evaluating earnings?",
    choices: ["To estimate sustainable, recurring earnings that will likely repeat in future years","Because it isn't a real cost","Because GAAP requires it","To make the company look worse"],
    answer: 0,
    explain: "The charge is real, but it isn't expected every year. Removing it, after tax, shows what the core business normally earns, which is what valuation multiples like P/E are meant to capture." },
  { id: "is-072", topic: "is", sub: "Non-recurring items", difficulty: 3, type: "mc",
    prompt: "A company reports net income of $600, which includes a one-time pre-tax restructuring charge of $200. With a 40% tax rate, what is <b>adjusted</b> net income excluding the charge?",
    choices: ["$800","$680","$600","$720"],
    answer: 3,
    explain: "After tax, the charge cost $200 × (1 − 0.40) = $120 of net income. Adjusted NI = $600 + $120 = $720. $800 adds back the full pre-tax amount and forgets that the charge also saved $80 of taxes." },
  { id: "is-073", topic: "is", sub: "Non-recurring items", difficulty: 1, type: "mc",
    prompt: "Where do the results of a <b>discontinued operation</b> (a division sold off this year) appear?",
    choices: ["Mixed into revenue and COGS as usual","Only on the balance sheet","As a separate line below income from continuing operations, shown net of tax","In operating expenses"],
    answer: 2,
    explain: "Discontinued operations are pulled out and reported separately, net of tax, just above net income. That keeps continuing operations comparable from year to year." },
  { id: "is-074", topic: "is", sub: "Revenue vs cash", difficulty: 3, type: "mc",
    prompt: "A consulting firm earned $90,000 of revenue in December. It collected $70,000 of cash in December, of which $10,000 was for November invoices. How much of <b>December's</b> revenue was still uncollected on December 31?",
    choices: ["$20,000","$30,000","$10,000","$40,000"],
    answer: 1,
    explain: "December cash for December work = $70,000 − $10,000 = $60,000. Uncollected December revenue = $90,000 − $60,000 = $30,000. $20,000 ($90,000 − $70,000) forgets that some of the cash belonged to November." },
  { id: "is-075", topic: "is", sub: "Traps", difficulty: 1, type: "mc",
    prompt: "Maya invests $20,000 of her savings to start a food truck business. How does this affect the business's income statement?",
    choices: ["No effect: it's an equity contribution (cash ↑, equity ↑)","Revenue +$20,000","Other income +$20,000","Expense +$20,000"],
    answer: 0,
    explain: "Money from owners is financing, not income. It raises cash and owner's equity (common stock) and shows up as a CFF inflow. It never touches the income statement." },
  { id: "is-076", topic: "is", sub: "Traps", difficulty: 1, type: "mc",
    prompt: "A bike shop receives a $50,000 bank loan. What happens to revenue?",
    choices: ["Revenue rises $50,000","Revenue rises by the interest rate × $50,000","Revenue falls $50,000","Nothing: a loan is a liability, not revenue"],
    answer: 3,
    explain: "Borrowing raises cash and debt, and it's a CFF inflow. Only the <b>interest</b> on the loan will later hit the income statement, as an expense." },
  { id: "is-077", topic: "is", sub: "Traps", difficulty: 2, type: "mc",
    prompt: "On January 1 a yoga studio prepays $12,000 for 12 months of rent. What rent expense appears on its <b>January</b> income statement?",
    choices: ["$12,000","$0","$1,000","$6,000"],
    answer: 2,
    explain: "The prepayment is recorded as a prepaid expense, an asset. Each month, $12,000 ÷ 12 = $1,000 is used up and expensed. Expensing the whole $12,000 in January would break the matching principle." },
  { id: "is-078", topic: "is", sub: "Traps", difficulty: 1, type: "mc",
    prompt: "This month a print shop collects $5,000 from a customer for a job completed and billed last month. What is the effect on <b>this month's revenue</b>?",
    choices: ["+$5,000","No effect","−$5,000","+$5,000 minus tax"],
    answer: 1,
    explain: "The revenue was recorded last month, when the job was done. This month's collection just swaps A/R for cash: Cash +$5,000, A/R −$5,000." },
  { id: "is-079", topic: "is", sub: "Capex vs expense", difficulty: 2, type: "mc",
    prompt: "On January 1 a dental clinic buys an X-ray machine for $60,000 cash (6-year life, no salvage, straight-line). What total expense related to the machine appears on this year's income statement?",
    choices: ["$10,000","$60,000","$0","$5,000"],
    answer: 0,
    explain: "The $60,000 is capitalized as PP&E and shows up as CFI capex. The IS only shows depreciation: $60,000 ÷ 6 = $10,000 for the year." },
  { id: "is-080", topic: "is", sub: "Traps", difficulty: 1, type: "mc",
    prompt: "A company declares and pays a $10,000 cash dividend. How does this affect <b>net income</b>?",
    choices: ["Net income falls $10,000","Net income falls $6,000 after tax","Net income rises $10,000","No effect on net income; retained earnings fall $10,000"],
    answer: 3,
    explain: "Dividends are a distribution of profit, not an expense. Net income is calculated first, then dividends reduce retained earnings directly. On the CFS, the payment is a $10,000 CFF outflow." },
  { id: "is-081", topic: "is", sub: "COGS", difficulty: 2, type: "mc",
    prompt: "A gift shop buys $40,000 of inventory and sells three-quarters of it for $70,000. What is its gross profit?",
    choices: ["$30,000","$70,000","$40,000","$52,500"],
    answer: 2,
    explain: "COGS = only the inventory sold = 75% × $40,000 = $30,000. GP = $70,000 − $30,000 = $40,000. $30,000 wrongly expenses all $40,000 of purchases. The unsold $10,000 is still inventory on the balance sheet." },
  { id: "is-082", topic: "is", sub: "COGS vs OpEx", difficulty: 1, type: "mc",
    prompt: "For a furniture manufacturer, which cost belongs in COGS?",
    choices: ["Salaries of the sales team","Wages of factory workers who build the furniture","The CEO's salary","Rent on the corporate headquarters"],
    answer: 1,
    explain: "COGS includes the direct costs of making the product: materials, factory labor, and factory overhead. Sales salaries, executive pay, and HQ rent are operating expenses (SG&A)." },
  { id: "is-083", topic: "is", sub: "Interest", difficulty: 3, type: "mc",
    prompt: "A company has $1,000 of debt that charges 5% cash interest plus 3% PIK (paid-in-kind) interest. What interest expense appears on the income statement for the year?",
    choices: ["$80","$50","$30","$48"],
    answer: 0,
    explain: "Both pieces are interest expense: 5% × $1,000 = $50 cash plus 3% × $1,000 = $30 PIK, for a total of $80. The PIK portion is added to the debt balance instead of being paid, so it's added back on the CFS. $48 is the after-tax hit to NI ($80 × 0.6)." },
  { id: "is-084", topic: "is", sub: "Operating income", difficulty: 2, type: "mc",
    prompt: "A company's operating income rose 10% this year, but its net income fell. Which explanation is most plausible?",
    choices: ["Revenue fell sharply","COGS rose faster than revenue","SG&A costs rose","Interest expense jumped after the company took on a large new loan"],
    answer: 3,
    explain: "Revenue, COGS, and SG&A all sit above operating income, which rose. So the drop must come from <b>below</b> EBIT: higher interest expense, a non-operating loss, or a higher tax charge." },
  { id: "is-085", topic: "is", sub: "Gross profit", difficulty: 3, type: "mc",
    prompt: "A retailer's revenue grows 10% (from $100M to $110M) while its gross margin falls from 40% to 35%. What happened to gross profit?",
    choices: ["It rose 10%","It rose 5%","It fell 3.75%","It fell 5%"],
    answer: 2,
    explain: "Old GP = 40% × $100M = $40M. New GP = 35% × $110M = $38.5M. Change = $38.5M ÷ $40M − 1 = −3.75%. Revenue growth doesn't help if margins shrink by more. \"Rose 5%\" subtracts the 5 margin points from the 10% growth, and \"fell 5%\" looks only at the margin drop; neither is how it works." },
  { id: "is-086", topic: "is", sub: "Margins", difficulty: 1, type: "mc",
    prompt: "A boutique has revenue of $250,000 and net income of $20,000. What is its net profit margin?",
    choices: ["12.5%","8%","20%","0.8%"],
    answer: 1,
    explain: "Net margin = Net income ÷ Revenue = $20,000 ÷ $250,000 = 0.08 = 8%. 12.5% flips the division ($250,000 ÷ $20,000 = 12.5), and 0.8% misplaces the decimal." },
  { id: "is-087", topic: "is", sub: "Margins", difficulty: 3, type: "mc",
    prompt: "A sporting-goods store has revenue of $400,000, a 30% gross margin, $70,000 of operating expenses, no interest, and a 40% tax rate. What is its net income?",
    choices: ["$30,000","$50,000","$20,000","$126,000"],
    answer: 0,
    explain: "GP = 30% × $400,000 = $120,000. EBIT = $120,000 − $70,000 = $50,000. Tax = 40% × $50,000 = $20,000, so NI = $30,000 (7.5% net margin). $126,000 treats the 30% as COGS instead of gross margin, and $20,000 is the tax." },
  { id: "is-088", topic: "is", sub: "Margins", difficulty: 1, type: "mc",
    prompt: "Which type of business typically has the <b>highest gross margin</b>?",
    choices: ["Grocery store","Car manufacturer","Gas station","Software (SaaS) company"],
    answer: 3,
    explain: "Once software is built, delivering one more copy costs very little (hosting and support), so gross margins are often 70–85%. Grocers and gas stations resell physical goods at thin markups, often 10–30% gross margins." },
  { id: "is-089", topic: "is", sub: "COGS vs OpEx", difficulty: 2, type: "mc",
    prompt: "A consulting firm reports “cost of services” instead of COGS. What would it most likely include?",
    choices: ["Office rent at headquarters","Advertising","Salaries of consultants doing billable client work","Interest on the firm's line of credit"],
    answer: 2,
    explain: "Service businesses have no inventory, but they still have direct delivery costs. For a consulting firm that's mainly the people doing the client work. Rent, ads, and interest are operating or financing costs." },
  { id: "is-090", topic: "is", sub: "Revenue", difficulty: 1, type: "mc",
    prompt: "A clothing brand has gross sales of $100,000, customer returns of $4,000, and early-payment discounts of $1,000. What is its <b>net revenue</b>?",
    choices: ["$100,000","$95,000","$96,000","$105,000"],
    answer: 1,
    explain: "Net revenue = Gross sales − returns − discounts = $100,000 − $4,000 − $1,000 = $95,000. Companies report revenue net of these reductions. $96,000 forgets the discounts." },
  { id: "is-091", topic: "is", sub: "Revenue recognition", difficulty: 2, type: "mc",
    prompt: "In December a coffee shop sells $5,000 of gift cards. Customers redeem $2,000 of them in December. How much December revenue comes from the gift cards?",
    choices: ["$2,000","$5,000","$3,000","$0"],
    answer: 0,
    explain: "Selling a gift card creates deferred revenue, a liability, because the shop still owes coffee. Revenue is recognized when cards are redeemed: $2,000. The remaining $3,000 is still a liability at month-end." },
  { id: "is-092", topic: "is", sub: "Matching principle", difficulty: 2, type: "mc",
    prompt: "An electronics store sells $200,000 of products this year and expects warranty repairs to cost 2% of sales, although no repairs have happened yet. How much warranty expense should it record this year?",
    choices: ["$0","$2,000","$200,000","$4,000"],
    answer: 3,
    explain: "Matching says the expected warranty cost belongs in the year of the sales: 2% × $200,000 = $4,000 of expense, plus a warranty liability. Waiting until repairs happen ($0) would put the cost in the wrong period." },
  { id: "is-093", topic: "is", sub: "Accrued expenses", difficulty: 3, type: "mc",
    prompt: "A shop's December electricity bill of $800 arrives and is paid in January. With a 40% tax rate, how does this bill affect <b>December</b> net income?",
    choices: ["−$800","$0","−$480","−$320"],
    answer: 2,
    explain: "The power was used in December, so it's a December expense even though it's unpaid (an accrued expense). Pre-tax −$800, tax savings +$320, NI −$480. $0 is what cash-basis thinking gives, and −$320 is the tax effect alone." },
  { id: "is-094", topic: "is", sub: "Interest", difficulty: 3, type: "mc",
    prompt: "A company has operating income of $300, interest expense of $50, and interest income of $10. With a 40% tax rate, what is net income?",
    choices: ["$150","$156","$180","$144"],
    answer: 1,
    explain: "Net interest expense = $50 − $10 = $40. Pre-tax = $300 − $40 = $260, and NI = $260 × 0.6 = $156. $150 ignores the interest income, $180 ignores all interest, and $144 subtracts the interest income instead of adding it." },
  { id: "is-095", topic: "is", sub: "SBC", difficulty: 2, type: "mc",
    prompt: "A startup pays its engineers $200,000 in cash salary and also grants them stock awards whose expense this year is $50,000. What total R&D compensation expense appears on the income statement?",
    choices: ["$250,000","$200,000","$50,000","$150,000"],
    answer: 0,
    explain: "Stock-based compensation is a real expense even though it's paid in stock: $200,000 + $50,000 = $250,000. On the CFS, the $50,000 is added back as non-cash. $200,000 counts only the cash pay." },
  { id: "is-096", topic: "is", sub: "COGS vs OpEx", difficulty: 1, type: "multi",
    prompt: "Which of these are <b>operating expenses</b>? Select all that apply.",
    choices: ["Rent","Marketing","Research & development","Office staff salaries","Interest expense","Income tax expense","Dividends paid"],
    answers: [0,1,2,3],
    explain: "Operating expenses are the costs of running the business: rent, marketing, R&D, and admin pay. Interest and taxes come below operating income, and dividends aren't expenses at all." },
  { id: "is-097", topic: "is", sub: "Building an IS", difficulty: 2, type: "multi",
    prompt: "A pet-grooming business has these activities this month. Which ones create a line on <b>this month's</b> income statement? Select all that apply.",
    choices: ["Grooming services performed and paid for in cash","Grooming done on credit; the customer pays next month","Buying a $3,000 grooming table","Paying this month's groomer wages","Receiving a bank loan","A customer prepaying for next month's grooming","Shampoo and supplies used up this month","The owner withdrawing $1,000 for personal use"],
    answers: [0,1,3,6],
    explain: "Revenue earned (cash or credit) counts, and so do expenses incurred (wages, supplies used). The table is capitalized, the loan is financing, the prepayment is deferred revenue, and an owner withdrawal reduces equity, not income." },
  { id: "is-098", topic: "is", sub: "Traps", difficulty: 2, type: "multi",
    prompt: "Which of these cash payments are <b>not</b> expenses on the income statement when they're made? Select all that apply.",
    choices: ["Repaying loan principal","Buying inventory that is still unsold","Paying a dividend","Purchasing a building","Paying this month's rent","Paying this month's interest"],
    answers: [0,1,2,3],
    explain: "Loan principal and dividends are financing flows. Unsold inventory and buildings are assets, which become expenses later as COGS or depreciation. This month's rent and interest are expenses of the current period." },
  { id: "is-099", topic: "is", sub: "Non-cash expenses", difficulty: 1, type: "multi",
    prompt: "Which of these are <b>non-cash</b> expenses? Select all that apply.",
    choices: ["Depreciation","Amortization of intangibles","Stock-based compensation","Asset impairment (write-down)","Employee salaries paid this month","Utility bills paid this month"],
    answers: [0,1,2,3],
    explain: "D&A, SBC, and impairments lower net income without using cash this period, so they're added back on the indirect CFS. Salaries and utilities paid this month are cash expenses." },
  { id: "is-100", topic: "is", sub: "EBITDA", difficulty: 2, type: "multi",
    prompt: "Starting from EBIT (operating income), which items do you add back to get standard EBITDA? Select all that apply.",
    choices: ["Depreciation","Amortization of acquired intangibles","Interest expense","Income tax expense","Rent expense","Stock-based compensation"],
    answers: [0,1],
    explain: "EBITDA = EBIT + D&A. Interest and taxes are already below EBIT, so you don't add them back again. Rent is a real operating cost. SBC is only added back in company-defined adjusted EBITDA, not standard EBITDA." },
  { id: "is-101", topic: "is", sub: "Net income vs cash", difficulty: 3, type: "multi",
    prompt: "Which of these make a company's net income <b>differ</b> from its operating cash flow this period? Select all that apply.",
    choices: ["Sales made on credit and not yet collected","Depreciation expense","Rent prepaid for the next six months","Wages earned by employees but unpaid at period-end","A cash sale of coffee","Wages earned and paid in cash in the same month"],
    answers: [0,1,2,3],
    explain: "Timing gaps (A/R, prepaids, accruals) and non-cash expenses (depreciation) separate profit from cash. A cash sale and wages paid in the same period hit net income and cash by the same amount." },
  { id: "is-102", topic: "is", sub: "EPS", difficulty: 2, type: "multi",
    prompt: "Which of these can add shares to the <b>diluted</b> EPS share count (when dilutive)? Select all that apply.",
    choices: ["In-the-money stock options","Convertible bonds","Restricted stock units (RSUs)","Convertible preferred stock","An ordinary bank term loan","Cash dividends paid"],
    answers: [0,1,2,3],
    explain: "Anything that could turn into common stock (options, RSUs, convertible bonds, convertible preferred) is counted in diluted shares if it lowers EPS. A plain loan and dividends don't create new shares." },
  { id: "is-103", topic: "is", sub: "Non-recurring items", difficulty: 2, type: "multi",
    prompt: "Which are typically treated as <b>non-recurring</b> items? Select all that apply.",
    choices: ["Restructuring charges","Goodwill impairment","A one-time lawsuit settlement","Gain on selling a division","Cost of goods sold","Employee salaries","Rent"],
    answers: [0,1,2,3],
    explain: "Restructurings, impairments, settlements, and one-off gains distort a single period, so they're often adjusted out. COGS, salaries, and rent recur every period." },
  { id: "is-104", topic: "is", sub: "Gross profit", difficulty: 3, type: "multi",
    prompt: "Holding everything else constant, which events would <b>reduce gross profit</b>? Select all that apply.",
    choices: ["The raw-material cost per unit rises","The company offers bigger sales discounts","More customers return products","The CEO gets a raise","Interest rates on the company's debt rise","A new advertising campaign launches"],
    answers: [0,1,2],
    explain: "Gross profit = net revenue − COGS. Higher unit costs raise COGS, and discounts and returns cut net revenue. CEO pay and advertising are operating expenses, and interest sits below EBIT, so none of those three touch gross profit." },
  { id: "is-105", topic: "is", sub: "IS vs BS", difficulty: 1, type: "multi",
    prompt: "Which items appear on the <b>income statement</b>? Select all that apply.",
    choices: ["Revenue","Cost of goods sold","Income tax expense","Earnings per share","Accounts receivable","Dividends paid","Capital expenditures","Retained earnings"],
    answers: [0,1,2,3],
    explain: "The IS runs from revenue down to net income and EPS. A/R and retained earnings are balance sheet items, dividends paid is a CFF item (and an equity reduction), and capex is a CFI item." },
  { id: "is-106", topic: "is", sub: "Revenue", difficulty: 3, type: "multi",
    prompt: "A software company's quarter: which items count as <b>revenue</b>? Select all that apply.",
    choices: ["Subscription service delivered this quarter","Venture capital funding received","A customer prepayment for next year's service","Professional services completed this quarter","Cash from selling an old server at its book value","Interest earned on the company's bank balance"],
    answers: [0,3],
    explain: "Revenue comes from delivering the company's main products and services. VC money is equity, a prepayment is deferred revenue, selling a server at book value is an asset sale with no gain, and interest earned is non-operating other income, not revenue." },
  { id: "is-107", topic: "is", sub: "COGS vs OpEx", difficulty: 2, type: "multi",
    prompt: "Which costs would a bakery include in <b>COGS</b>? Select all that apply.",
    choices: ["Flour and eggs used in goods sold","Bags and boxes for goods sold","Shipping cost to have ingredients delivered (freight-in)","Facebook ads","Fees paid to the outside accountant","Interest on the oven loan"],
    answers: [0,1,2],
    explain: "COGS includes everything needed to get the sold product into the customer's hands: ingredients, packaging, and inbound freight. Ads and accounting fees are operating expenses, and interest sits below EBIT." },
  { id: "is-108", topic: "is", sub: "EBITDA", difficulty: 3, type: "multi",
    prompt: "Holding everything else constant, which changes would <b>increase EBITDA</b>? Select all that apply.",
    choices: ["Revenue increases","SG&A is cut","Interest expense falls","Depreciation expense falls","The tax rate drops","COGS per unit falls"],
    answers: [0,1,5],
    explain: "EBITDA = revenue − COGS − operating expenses excluding D&A. Raising revenue or cutting COGS or SG&A raises it. Interest, taxes, and D&A are excluded by definition, so changes in them leave EBITDA unchanged even though they change net income." },
  { id: "is-109", topic: "is", sub: "Operating income", difficulty: 2, type: "multi",
    prompt: "Which statements about <b>operating income</b> are true? Select all that apply.",
    choices: ["It is calculated before interest expense","It is often called EBIT","It is calculated after subtracting depreciation and amortization","It is calculated after income taxes","It is reduced by dividends paid"],
    answers: [0,1,2],
    explain: "Operating income = gross profit − all operating expenses, D&A included. It comes before interest and taxes (hence the name EBIT). Dividends never appear on the income statement." },
  { id: "is-110", topic: "is", sub: "Traps", difficulty: 3, type: "multi",
    prompt: "Which bookkeeping mistakes would <b>overstate</b> net income? Select all that apply.",
    choices: ["Recording a customer's prepayment for next year as revenue now","Capitalizing a routine repair instead of expensing it","Forgetting to accrue December wages that are paid in January","Expensing a new delivery truck instead of capitalizing it","Recording a bank loan as revenue","Recording the same supplier invoice as an expense twice"],
    answers: [0,1,2,4],
    explain: "Booking unearned cash or a loan as revenue overstates income, and so does leaving out an expense, whether by capitalizing a routine cost or skipping an accrual. Expensing a truck or double-counting a bill <b>understates</b> income." }
]);
